"category\\\": \\\"Metric\\\"\\n    }, {\\n        \\\"name\\\": \\\"through_packets\\\",\\n        \\\"type\\\": \\\"long\\\",\\n        \\\"category\\\": \\\"Metric\\\"\\n    }, {\\n        \\\"name\\\": \\\"sessions\\\",\\n        \\\"type\\\": \\\"long\\\",\\n        \\\"category\\\": \\\"Metric\\\"\\n    }],\\n    \\\"data\\\": {\\n        \\\"resultType\\\": \\\"object\\\",\\n        \\\"result\\\": []\\n    },\\n    \\\"originalUrl\\\": \\\"http://192.168.44.55:9999/?query=SELECT app_subcategory AS app_subcategory, SUM(common_c2s_byte_num + common_s2c_byte_num) AS total_bytes, SUM(traffic_inbound_byte) AS inbound_bytes, SUM(traffic_outbound_byte) AS outbound_bytes, SUM(traffic_internal_byte) AS internal_bytes, SUM(traffic_through_byte) AS through_bytes, SUM(common_c2s_pkt_num + common_s2c_pkt_num) AS total_packets, SUM(traffic_inbound_pkt) AS inbound_packets, SUM(traffic_outbound_pkt) AS outbound_packets, SUM(traffic_internal_pkt) AS internal_packets, SUM(traffic_through_pkt) AS through_packets, SUM(common_sessions) AS sessions FROM metric_application WHERE stat_time >= toDateTime(1150050173)-523209900 AND stat_time < toDateTime(1673260073)-523209900 AND app_subcategory IN (\'multimedia-streaming\',\'social-networking\',\'file-sharing\',\'gaming\',\'email\',\'voip-video\') GROUP BY app_subcategory &format=json&option=real-time\\\",\\n    \\\"msg\\\": \\\"OK\\\"\\n}\",\n  \"description\" : null,\n  \"requestBodyDefinition\" : null,\n  \"responseBodyDefinition\" : {\n    \"name\" : \"\",\n    \"value\" : \"\",\n    \"description\" : \"\",\n    \"required\" : false,\n    \"dataType\" : \"Object\",\n    \"type\" : null,\n    \"defaultValue\" : null,\n    \"validateType\" : \"\",\n    \"error\" : \"\",\n    \"expression\" : \"\",\n    \"children\" : [ {\n      \"name\" : \"status\",\n      \"value\" : \"200\",\n      \"description\" : \"\",\n      \"required\" : false,\n      \"dataType\" : \"Integer\",\n      \"type\" : null,\n      \"defaultValue\" : null,\n    