(QUANTILE(tcp_lostlen_ratio,0.50), 4) AS tcp_lostlen_percent_p50, ROUND(QUANTILE(tcp_lostlen_ratio,0.90), 4) AS tcp_lostlen_percent_p90, ROUND(QUANTILE(tcp_lostlen_ratio,0.95), 4) AS tcp_lostlen_percent_p95, ROUND(QUANTILE(tcp_lostlen_ratio,0.99), 4) AS tcp_lostlen_percent_p99, ROUND(AVG(pkt_retrans_ratio), 4) AS pkt_retrans_percent_avg, ROUND(QUANTILE(pkt_retrans_ratio,0.50), 4) AS pkt_retrans_percent_p50, ROUND(QUANTILE(pkt_retrans_ratio,0.90), 4) AS pkt_retrans_percent_p90, ROUND(QUANTILE(pkt_retrans_ratio,0.95), 4) AS pkt_retrans_percent_p95, ROUND(QUANTILE(pkt_retrans_ratio,0.99), 4) AS pkt_retrans_percent_p99 FROM ${tableName} WHERE <#if cycle?default(\'\')?trim? length gt 0 && cycle ==1> stat_time >= ${startTime}-${timeDiff} AND stat_time < ${endTime}-${timeDiff} <#else> stat_time >= ${startTime} AND stat_time < ${endTime} </#if><#if filter?default(\'\')?trim? length gt 0> ${filter} </#if>\\\",\\\"option\\\":\\\"real-time\\\",\\\"format\\\":\\\"json\\\"}\"\r\n\r\nvar result  = freeMarkerUtil.processTemplateIntoString(\"applicationPerformanceOverviewDrilldownDimensioAllNetworkAnalysis\",q,parameter);\r\nvar param = jsonUtil.toBean(result,HashMap.class);\r\nvar galaxyRes = getGalaxyResult(param);\r\n\r\n\r\n/**\r\n * 处理galaxy返回的数据结果 将新结果返回前端界面\r\n */\r\nvar result = objHandle(galaxyRes);\r\n\r\nreturn result;');
