\nimport net.geedge.common.utils.JSONUtil as jsonUtil;\r\nimport \'@/pre/timeHandleNone\' as preHandle;\r\nimport \'@/pre/typeHandle\' as typeHandle;\r\nimport \'@/post/object\' as objHandle\r\nimport \'@/public/getGalaxyResult\' as getGalaxyResult\r\nimport \'@/public/getPercentile\' as getPercentile\r\nimport \'@/public/toHump\' as toHump\r\n\r\n\r\n/**\r\n * 入参整理 包括调用公共函数\r\n */\r\nvar parameter={\r\n    \"startTime\":startTime,\r\n    \"endTime\":endTime,\r\n    \"q\":q,\r\n    \"type\":type\r\n}\r\n\r\npreHandle(parameter);\r\ntypeHandle(parameter);\r\n\r\n/**\r\n * 接口sql相关内容整理 通过freemarker模板生成最后执行语句\r\n */\r\nvar q = \"{\\\"query\\\":\\\"SELECT TIME_FLOOR_WITH_FILL(stat_time,\'PT${step}S\',\'zero\') AS stat_time, ${dimension} AS ${label}, SUM(common_c2s_byte_num + common_s2c_byte_num) AS bytes_total, SUM(traffic_inbound_byte) AS inbound_bytes, SUM(traffic_outbound_byte) AS outbound_bytes, SUM(traffic_internal_byte) AS internal_bytes, SUM(traffic_through_byte) AS through_bytes, SUM(common_c2s_pkt_num + common_s2c_pkt_num) AS packets_total, SUM(traffic_inbound_pkt) AS inbound_packets, SUM(traffic_outbound_pkt) AS outbound_packets, SUM(traffic_internal_pkt) AS internal_packets, SUM(traffic_through_pkt) AS through_packets, SUM(common_sessions) AS sessions, IFNULL(ROUND(AVG(avg_establish_latency_ms), 4),0) AS establish_latency_ms_avg, IFNULL(ROUND(AVG(avg_http_response_latency_ms), 4),0) AS http_response_latency_avg, IFNULL(ROUND(AVG(avg_ssl_con_latency_ms), 4),0) AS ssl_con_latency_avg, IFNULL(ROUND(AVG(tcp_lostlen_ratio), 4),0) AS tcp_lostlen_percent_avg, IFNULL(ROUND(AVG(pkt_retrans_ratio), 4),0) AS pkt_retrans_percent_avg FROM ${tableName} WHERE stat_time >= ${startTime} AND stat_time < ${endTime} AND (${q})<#if filter?default(\'\')?trim? length gt 0> ${filter} </#if> GROUP BY stat_time,${label} ORDER BY stat_time ASC\\\",\\\"option\\\":\\\"real-time\\\",\\\"format\\\":\\\"json\\\"}\"\r\n\r\nvar result  = freeMarkerUtil.processTemplateIntoString(\"applicationPerformanceOverviewDrilldownDrilldownDimensionTrafficGraph\",q,parameter);\r\nvar param = jsonUtil.toBean(result,HashMap.class);\r\nvar result = getGalaxyResult(param);\r\n\r\n\r\n/**\r\n * 处理galaxy返回的数据结果 将新结果返回前端界面\r\n */\r\nif(result.success){\r\n	var o = {};\r\n	o.resultType=\"object\";\r\n	var old = new ArrayList();\r\n	var list = result.data;\r\n	var newList = new ArrayList();\r\n	for(i,j in list){\r\n		newList.add(list[i]);\r\n	}\r\n	if(list.length > 0){\r\n		for(i,j in list){\r\n			var pojo = list[i];\r\n			var tempObj= {};\r\n			for (key,value in pojo){\r\n				if(key.indexOf(\"stat_time\") != -1){\r\n					tempObj[\'statTime\'] = pojo[key]\r\n				}else if(key.indexOf(\"bytes_total\") != -1){\r\n					tempObj[\'totalBitsRate\'] = (pojo[key].asDouble() / parameter.step).toFixed(2).asDouble() * 8\r\n				}else if(key.indexOf(\"packets_total\") != -1){\r\n					tempObj[\'totalPacketsRate\'] = (pojo[key].asDouble() / parameter.step).toFixed(2)\r\n				}else if(key.indexOf(\"sessions\") != -1){\r\n					tempObj[\'totalSessionsRate\'] = (pojo[key].asDouble() / parameter.step).toFixed(2)\r\n				}else if(key.indexOf(\"inbound_bytes\") != -1){\r\n					tempObj[\'inboundBitsRate\'] = (pojo[key].asDouble() / parameter.step).toFixed(2).asDouble() * 8\r\n				}else if(key.indexOf(\"inbound_packets\") != -1){\r\n					tempObj[\'inboundPacketsRate\'] = (pojo[key].asDouble() / parameter.step).toFixed(2)\r\n				}else if(key.indexOf(\"outbound_bytes\") != -1){\r\n					tempObj[\'outboundBitsRate\'] = (pojo[key].asDouble() / parameter.step).toFixed(2).asDouble() * 8\r\n				}else if(key.indexOf(\"outbound_packets\") != -1){\r\n					tempObj[\'outboundPacketsRate\'] = (pojo[key].asDouble() / parameter.step).toFixed(2)\r\n				}else if(key.indexOf(\"internal_bytes\") != -1){\r\n					tempObj[\'internalBitsRate\'] = (pojo[key].asDouble() / parameter.step).toFixed(2).asDouble() * 8\r\n				}else if(key.indexOf(\"internal_packets\") != -1){\r\n					tempObj[\'internalPacketsRate\'] = (pojo[key].asDouble() / parameter.step).toFixed(2)\r\n				}else if(key.indexOf(\"through_bytes\") != -1){\r\n					tempObj[\'throughBitsRate\'] = (pojo[key].asDouble() / parameter.step).toFixed(2).asDouble() * 8\r\n				}else if(key.indexOf(\"through_packets\") != -1){\r\n					tempObj[\'throughPacketsRate\'] = (pojo[key].asDouble() / parameter.step).toFixed(2)\r\n				}else if(key.indexOf(\"establish_latency_ms_avg\") != -1){\r\n					tempObj[\'establishLatencyMsAvg\'] = pojo[key]\r\n				}else if(key.indexOf(\"http_response_latency_avg\") != -1){\r\n					tempObj[\'httpResponseLatencyAvg\'] = pojo[key]\r\n				}else if(key.indexOf(\"ssl_con_latency_avg\") != -1){\r\n					tempObj[\'sslConLatencyAvg\'] = pojo[key]\r\n				}else if(key.indexOf(\"tcp_lostlen_percent_avg\") != -1){\r\n					tempObj[\'tcpLostlenPercentAvg\'] = pojo[key]\r\n				}else if(key.indexOf(\"pkt_retrans_percent_avg\") != -1){\r\n					tempObj[\'pktRetransPercentAvg\'] = pojo[key]\r\n				}\r\n			}\r\n			list[i] = tempObj;\r\n		}\r\n		var bytes = [];\r\n		var packets = [];\r\n		var sessions = [];\r\n		var establishLatencyMs = [];\r\n		var httpResponseLatency = [];\r\n		var sslConLatency = [];\r\n		var tcpLostlenPercent = [];\r\n		var pktRetransPercent = [];\r\n		for(key,value in list[0]){\r\n			if(key.indexOf(\"Bits\") != -1){\r\n				bytes.push(key);\r\n			} else if(key.indexOf(\"Packets\") != -1){\r\n				packets.push(key);\r\n			} else if(key.indexOf(\"Sessions\") != -1){\r\n				sessions.push(key);\r\n			} else if(key.indexOf(\"establishLatencyMsAvg\") != -1){\r\n				establishLatencyMs.push(key);\r\n			} else if(key.indexOf(\"httpResponseLatencyAvg\") != -1){\r\n				httpResponseLatency.push(key);\r\n			} else if(key.indexOf(\"sslConLatencyAvg\") != -1){\r\n				sslConLatency.push(key);\r\n			} else if(key.indexOf(\"tcpLostlenPercentAvg\") != -1){\r\n				tcpLostlenPercent.push(key);\r\n			} else if(key.indexOf(\"pktRetransPercentAvg\") != -1){\r\n				pktRetransPercent.push(key);\r\n			}\r\n		}\r\n		var map = new HashMap();\r\n		map.put(\"totalBitsRate\",\"bytes_total\");\r\n		map.put(\"totalPacketsRate\",\"packets_total\");\r\n		map.put(\"totalSessionsRate\",\"sessions\");\r\n		map.put(\"inboundBitsRate\",\"inbound_bytes\");\r\n		map.put(\"inboundPacketsRate\",\"inbound_packets\");\r\n		map.put(\"outboundBitsRate\",\"outbound_bytes\");\r\n		map.put(\"outboundPacketsRate\",\"outbound_packets\");\r\n		map.put(\"internalBitsRate\",\"internal_bytes\");\r\n		map.put(\"internalPacketsRate\",\"internal_packets\");\r\n		map.put(\"throughBitsRate\",\"through_bytes\");\r\n		map.put(\"throughPacketsRate\",\"through_packets\");\r\n		map.put(\"establishLatencyMsAvg\",\"establish_latency_ms_avg\");\r\n		map.put(\"httpResponseLatencyAvg\",\"http_response_latency_avg\");\r\n		map.put(\"sslConLatencyAvg\",\"ssl_con_latency_avg\");\r\n		map.put(\"tcpLostlenPercentAvg\",\"tcp_lostlen_percent_avg\");\r\n		map.put(\"pktRetransPercentAvg\",\"pkt_retrans_percent_avg\");\r\n		var type = {};\r\n		type.bytes = bytes;\r\n		type.packets = packets;\r\n		type.sessions = sessions;\r\n		type.establishLatencyMs = establishLatencyMs;\r\n		type.httpResponseLatency = httpResponseLatency;\r\n		type.sslConLatency = sslConLatency;\r\n		type.tcpLostlenPercent = tcpLostlenPercent;\r\n		type.pktRetransPercent = pktRetransPercent;\r\n		for(key,value in type){\r\n			var obj = {};\r\n			obj.type = key;\r\n			var typeKey = type[key];\r\n			for(m,n in typeKey){\r\n				var zong = {};\r\n				var analysis = {};\r\n				var values = new ArrayList();\r\n				list.sort((a,b)=>a.statTime.asDouble()-b.statTime.asDouble());\r\n				var sumValue = 0;\r\n				for(i,j in list){\r\n					var pojo = list[i];\r\n					var tempArray = new ArrayList();\r\n					tempArray.add(pojo[\"statTime\"]);\r\n					tempArray.add(pojo[typeKey[m]].asDouble());\r\n					values.add(tempArray);\r\n				}\r\n				for(i,j in newList){\r\n					var pojo = newList[i];\r\n					var field = map.get(typeKey[m]);\r\n					var value = pojo[field];\r\n					sumValue += value.asDouble();\r\n				}\r\n				analysis.avg =  (sumValue.asDouble()/parameter.timeDiff).toFixed(2);\r\n				if(key==\"bytes\"){\r\n					analysis.avg = analysis.avg.asDouble() * 8;\r\n				}\r\n				analysis.avg=analysis.avg+\"\";\r\n				\r\n				var plist = [];\r\n				for(i,j in values){\r\n					plist.push(values[i][1].asDouble());\r\n				}\r\n				analysis.max = plist.max()+\"\";\r\n				analysis.min = plist.min()+\"\";\r\n				analysis.p95 = getPercentile(plist, 0.95)+\"\";\r\n				\r\n				zong.values = values;\r\n				zong.analysis = analysis;\r\n				\r\n				obj[typeKey[m]] = zong;\r\n			}\r\n			old.add(obj);\r\n		}\r\n		var len = old[0][\"totalBitsRate\"][\"values\"].length;\r\n		for(a,b in old){\r\n			if(old[a].type == \'bytes\' || old[a].type == \'packets\'){\r\n				var other = {};\r\n				var analysis = {};\r\n				var values = new ArrayList();\r\n				var sumValue = 0;\r\n				for(i in range(0,len-1)){\r\n					var sum = 0;\r\n					var tempArray = new ArrayList();\r\n					for(c,d in old[a]){\r\n						if(c != \'type\'){\r\n							if(c.indexOf(\"total\") != -1){\r\n								sum += old[a][c][\"values\"][i][1];\r\n							} else {\r\n								sum -= old[a][c][\"values\"][i][1];\r\n							}\r\n						}\r\n					}\r\n					sum = sum.asDouble() > 0 ? sum:0;\r\n					tempArray.add(old[0][\"totalBitsRate\"][\"values\"][i][0]);\r\n					tempArray.add(sum.toFixed(2).asDouble());\r\n					values.add(tempArray);\r\n					sumValue += sum.asDouble();\r\n				}\r\n				analysis.avg = Math.round((sumValue / len)*100)/100 + \"\";\r\n					\r\n				var plist = [];\r\n				for(i,j in values){\r\n					plist.push(values[i][1].asDouble());\r\n				}\r\n				analysis.max = plist.max()+\"\";\r\n				analysis.min = plist.min()+\"\";\r\n				analysis.p95 = getPercentile(plist, 0.95)+\"\";\r\n				\r\n				other.values = values;\r\n				other.analysis = analysis;\r\n				old[a].other = other;\r\n			}\r\n		}\r\n	}\r\n	o.result = old;\r\n	result.code=200;\r\n 	result.data=o;\r\n 	result.msg = result.message;\r\n 	result.message=null;\r\n}\r\nreturn result;');
