INSERT INTO `magic_api_file` VALUES ('/api/interface/application/performance/overview/drilldown/各维度HTTP响应延迟.ms', '{\n  \"properties\" : { },\n  \"id\" : \"copy1673337109464d83642\",\n  \"script\" : null,\n  \"groupId\" : \"17d545d31dc94a3d997e0c35db420305\",\n  \"name\" : \"各维度HTTP响应延迟\",\n  \"createTime\" : null,\n  \"updateTime\" : 1696848001528,\n  \"lock\" : null,\n  \"createBy\" : null,\n  \"updateBy\" : \"admin\",\n  \"path\" : \"/dimensionHttpResponseDelay\",\n  \"method\" : \"GET\",\n  \"parameters\" : [ {\n    \"name\" : \"startTime\",\n    \"value\" : \"1672988638\",\n    \"description\" : null,\n    \"required\" : true,\n    \"dataType\" : \"Long\",\n    \"type\" : null,\n    \"defaultValue\" : null,\n    \"validateType\" : null,\n    \"error\" : null,\n    \"expression\" : null,\n    \"children\" : null\n  }, {\n    \"name\" : \"endTime\",\n    \"value\" : \"1672988738\",\n    \"description\" : null,\n    \"required\" : true,\n    \"dataType\" : \"Long\",\n    \"type\" : null,\n    \"defaultValue\" : null,\n    \"validateType\" : null,\n    \"error\" : null,\n    \"expression\" : null,\n    \"children\" : null\n  }, {\n    \"name\" : \"type\",\n    \"value\" : \"ip\",\n    \"description\" : null,\n    \"required\" : true,\n    \"dataType\" : \"String\",\n    \"type\" : null,\n    \"defaultValue\" : null,\n    \"validateType\" : null,\n    \"error\" : null,\n    \"expression\" : null,\n    \"children\" : null\n  }, {\n    \"name\" : \"q\",\n    \"value\" : \"server_country_region=\'China\'\",\n    \"description\" : null,\n    \"required\" : true,\n    \"dataType\" : \"String\",\n    \"type\" : null,\n    \"defaultValue\" : null,\n    \"validateType\" : null,\n    \"error\" : null,\n    \"expression\" : null,\n    \"children\" : null\n  }, {\n    \"name\" : \"params\",\n    \"value\" : \"\'116.178.236.216\',\'116.178.236.217\',\'116.178.78.195\'\",\n    \"description\" : null,\n    \"required\" : true,\n    \"dataType\" : \"String\",\n    \"type\" : null,\