ound_packets, IF(client_zone = \'external\' AND server_zone = \'internal\' , SUM(common_s2c_byte_num), IF(client_zone = \'internal\' AND server_zone = \'external\', SUM(common_c2s_byte_num), 0)) AS outbound_bytes, IF(client_zone = \'external\' AND server_zone = \'internal\' , SUM(common_s2c_pkt_num), IF(client_zone = \'internal\' AND server_zone = \'external\', SUM(common_c2s_pkt_num), 0)) AS outbound_packets, IF(client_zone = \'internal\' AND server_zone = \'internal\' , SUM(common_s2c_byte_num + common_c2s_byte_num),0) AS internal_bytes, IF(client_zone = \'internal\' AND server_zone = \'internal\' , SUM(common_s2c_pkt_num + common_c2s_pkt_num), 0) AS internal_packets, IF(client_zone = \'external\' AND server_zone = \'external\' , SUM(common_s2c_byte_num + common_c2s_byte_num),0) AS external_bytes, IF(client_zone = \'external\' AND server_zone = \'external\' , SUM(common_s2c_pkt_num + common_c2s_pkt_num), 0) AS external_packets FROM session_record_cn WHERE common_recv_time >= 1694062927 AND common_recv_time < 1694066527 AND notEmpty(ip)   AND (client_asn = \'$param\')  GROUP BY ip,client_zone,server_zone ) GROUP BY ip  ORDER BY total_bytes desc   LIMIT 10 &format=json&option=real-time\",\n      \"description\" : \"\",\n      \"required\" : false,\n      \"dataType\" : \"String\",\n      \"type\" : null,\n      \"defaultValue\" : null,\n      \"validateType\" : \"\",\n      \"error\" : \"\",\n      \"expression\" : \"\",\n      \"children\" : [ ]\n    }, {\n      \"name\" : \"msg\",\n      \"value\" : \"OK\",\n      \"description\" : \"\",\n      \"required\" : false,\n      \"dataType\" : \"String\",\n      \"type\" : null,\n      \"defaultValue\" : null,\n      \"validateType\" : \"\",\n      \"error\" : \"\",\n      \"expression\" : \"\",\n      \"children\" : [ ]\n    } ]\n  }\n}\r\n================================\r\nimport http;\r\nimport net.geedge.common.utils.FreeMarkerUtil as freeMarkerUtil;\r\nimport net.geedge.common.utils.JSONUtil as jsonUtil;\r\nimport \'@/pre/timeHandleNone\' as preHandle;\r\nimport \'@/pre/typeHandle2nd\' as typeHandle;\r\nimport \'@/post/table\' as objHandle\r\nimport \'@/public/getGalaxyResult\' as getGalaxyResult\r\nimport \'@/public/orderHandle\' as orderHandle\r\n\r\n/**\r\n * 入参整理 包括调用公共函数\r\n */\r\nvar parameter={\r\n    \"startTime\":startTime,\r\n    \"endTime\":endTime,\r\n	\"params\":params,\r\n    \"limit\":limit,\r\n    \"type\":type,\r\n    \"q\":q,\r\n    \"orderBy\":orderBy\r\n}\r\nparameter.orderBy = orderHandle(parameter.orderBy);\r\npreHandle(parameter);\r\ntypeHandle(parameter);\r\n\r\n/**\r\n * 接口sql相关内容整理 通过freemarker模板生成最后执行语句\r\n */\r\nvar q = \"{\\r\\n    \\\"query\\\":\\\"SELECT ${label} AS ${label}, SUM(bytes_total) AS total_bytes, SUM(packets_total) AS total_packets, SUM(sessions) AS sessions, SUM(inbound_bytes) AS inbound_bytes, SUM(inbound_packets) AS inbound_packets, SUM(outbound_bytes) AS outbound_bytes, SUM(outbound_packets) AS outbound_packets, SUM(internal_bytes) AS internal_bytes, SUM(internal_packets) AS internal_packets, SUM(external_bytes) AS through_bytes, SUM(external_packets) AS through_packets FROM ( SELECT ${dimension} as ${label}, SUM(common_s2c_byte_num + common_c2s_byte_num) AS bytes_total, SUM(common_s2c_pkt_num + common_c2s_pkt_num) AS packets_total, SUM(common_sessions) AS sessions, IF(client_zone = \\\'internal\\\' AND server_zone = \\\'external\\\' , SUM(common_s2c_byte_num), IF(client_zone = \\\'external\\\' AND server_zone = \\\'internal\\\', SUM(common_c2s_byte_num), 0)) AS inbound_bytes, IF(client_zone = \\\'internal\\\' AND server_zone = \\\'external\\\' , SUM(common_s2c_pkt_num), IF(client_zone = \\\'external\\\' AND server_zone = \\\'internal\\\', SUM(common_c2s_pkt_num), 0)) AS inbound_packets, IF(client_zone = \\\'external\\\' AND server_zone = \\\'internal\\\' , SUM(common_s2c_byte_num), IF(client_zone = \\\'internal\\\' AND server_zone = \\\'external\\\', SUM(common_c2s_byte_num), 0)) AS outbound_bytes, IF(client_zone = \\\'external\\\' AND server_zone = \\\'internal\\\' , SUM(common_s2c_pkt_num), IF(client_zone = \\\'internal\\\' AND server_zone = \\\'external\\\', SUM(common_c2s_pkt_num), 0)) AS outbound_packets, IF(client_zone = \\\'internal\\\' AND server_zone = \\\'internal\\\' , SUM(common_s2c_byte_num + common_c2s_byte_num),0) AS internal_bytes, IF(client_zone = \\\'internal\\\' AND server_zone = \\\'internal\\\' , SUM(common_s2c_pkt_num + common_c2s_pkt_num), 0) AS internal_packets, IF(client_zone = \\\'external\\\' AND server_zone = \\\'external\\\' , SUM(common_s2c_byte_num + common_c2s_byte_num),0) AS external_bytes, IF(client_zone = \\\'external\\\' AND server_zone = \\\'external\\\' , SUM(common_s2c_pkt_num + common_c2s_pkt_num), 0) AS external_packets FROM session_record_cn WHERE common_recv_time >= ${startTime} AND common_recv_time < ${endTime} AND notEmpty(${label}) <#if params?default(\'\')?trim? length gt 0> AND ${label} IN (${params})</#if> <#if q?default(\\\'\\\')?trim? length gt 0> AND (${q}) </#if> GROUP BY ${label},client_zone,server_zone ) GROUP BY ${label} <#if orderBy?default(\\\'\\\')?trim? length gt 0> ORDER BY ${orderBy} desc <#else> ORDER BY total_bytes desc </#if> <#if limit?default(\\\'\\\')?trim? length gt 0> LIMIT ${limit} </#if>\\\",\\r\\n    \\\"option\\\": \\\"real-time\\\",\\r\\n    \\\"format\\\": \\\"json\\\"\\r\\n}\"\r\n\r\nvar result  = freeMarkerUtil.processTemplateIntoString(\"applicationPerformanceOverviewDrilldownDimensionTrafficAnalysis\",q,parameter);\r\nvar param = jsonUtil.toBean(result,HashMap.class);\r\nvar galaxyRes = getGalaxyResult(param);\r\n\r\n\r\n/**\r\n * 处理galaxy返回的数据结果 将新结果返回前端界面\r\n */\r\nvar result = objHandle(galaxyRes);\r\n\r\nreturn result;');
