}, {\\n        \\\"name\\\": \\\"inbound_bytes\\\",\\n        \\\"type\\\": \\\"long\\\",\\n        \\\"category\\\": \\\"Metric\\\"\\n    }, {\\n        \\\"name\\\": \\\"outbound_bytes\\\",\\n        \\\"type\\\": \\\"long\\\",\\n        \\\"category\\\": \\\"Metric\\\"\\n    }, {\\n        \\\"name\\\": \\\"internal_bytes\\\",\\n        \\\"type\\\": \\\"long\\\",\\n        \\\"category\\\": \\\"Metric\\\"\\n    }, {\\n        \\\"name\\\": \\\"through_bytes\\\",\\n        \\\"type\\\": \\\"long\\\",\\n        \\\"category\\\": \\\"Metric\\\"\\n    }, {\\n        \\\"name\\\": \\\"total_packets\\\",\\n        \\\"type\\\": \\\"long\\\",\\n        \\\"category\\\": \\\"Metric\\\"\\n    }, {\\n        \\\"name\\\": \\\"inbound_packets\\\",\\n        \\\"type\\\": \\\"long\\\",\\n        \\\"category\\\": \\\"Metric\\\"\\n    }, {\\n        \\\"name\\\": \\\"outbound_packets\\\",\\n        \\\"type\\\": \\\"long\\\",\\n        \\\"category\\\": \\\"Metric\\\"\\n    }, {\\n        \\\"name\\\": \\\"internal_packets\\\",\\n        \\\"type\\\": \\\"long\\\",\\n        \\\"category\\\": \\\"Metric\\\"\\n    }, {\\n        \\\"name\\\": \\\"through_packets\\\",\\n        \\\"type\\\": \\\"long\\\",\\n        \\\"category\\\": \\\"Metric\\\"\\n    }, {\\n        \\\"name\\\": \\\"sessions\\\",\\n        \\\"type\\\": \\\"long\\\",\\n        \\\"category\\\": \\\"Metric\\\"\\n    }, {\\n        \\\"name\\\": \\\"establish_latency_ms_avg\\\",\\n        \\\"type\\\": \\\"double\\\",\\n        \\\"category\\\": \\\"Metric\\\"\\n    }, {\\n        \\\"name\\\": \\\"http_response_latency_avg\\\",\\n        \\\"type\\\": \\\"double\\\",\\n        \\\"category\\\": \\\"Metric\\\"\\n    }, {\\n        \\\"name\\\": \\\"ssl_con_latency_avg\\\",\\n        \\\"type\\\": \\\"double\\\",\\n        \\\"category\\\": \\\"Metric\\\"\\n    }, {\\n        \\\"name\\\": \\\"tcp_lostlen_percent_avg\\\",\\n        \\\"type\\\": \\\"double\\\",\\n        \\\"category\\\": \\\"Metric\\\"\\n    }, {\\n        \\\"name\\\": \\\"pkt_retrans_percent_avg\\\",\\n        \\\"type\\\": \\\"double\\\",\\n        \\\"category\\\": \\\"Metric\\\"\\n    }],\\n    \\\"data\\\": {\\n        \\\"resultType\\\": \\\"matrix\\\",\\n        \\\"result\\\": []\\n    },\\n    \\\"originalUrl\\\": \\\"http://192.168.44.55:9999/?query=SELECT TIME_FLOOR_WITH_FILL(stat_time,\'PT1M\',\'zero\') AS stat_time, SUM(common_c2s_byte_num + common_s2c_byte_num) AS total_bytes, SUM(traffic_inbound_byte) AS inbound_bytes, SUM(traffic_outbound_byte) AS outbound_bytes, SUM(traffic_internal_byte) AS internal_bytes, SUM(traffic_through_byte) AS through_bytes, SUM(common_c2s_pkt_num + common_s2c_pkt_num) AS total_packets, SUM(traffic_inbound_pkt) AS inbound_packets, SUM(traffic_outbound_pkt) AS outbound_packets, SUM(traffic_internal_pkt) AS internal_packets, SUM(traffic_through_pkt) AS through_packets, SUM(common_sessions) AS sessions, IFNULL(ROUND(AVG(avg_establish_latency_ms), 4),0) AS establish_latency_ms_avg, IFNULL(ROUND(AVG(avg_http_response_latency_ms), 4),0) AS http_response_latency_avg, IFNULL(ROUND(AVG(avg_ssl_con_latency_ms), 4),0) AS ssl_con_latency_avg, IFNULL(ROUND(AVG(tcp_lostlen_ratio), 4),0) AS tcp_lostlen_percent_avg, IFNULL(ROUND(AVG(pkt_retrans_ratio), 4),0) AS pkt_retrans_percent_avg FROM metric_application WHERE stat_time >= 1 AND stat_time < 1673315583 GROUP BY stat_time ORDER BY stat_time ASC&format=json&option=real-time\\\",\\n    \\\"msg\\\": \\\"OK\\\"\\n}\",\n  \"description\" : null,\n  \"requestBodyDefinition\" : null,\n  \"responseBodyDefinition\" : {\n    \"name\" : \"\",\n    \"value\" : \"\",\n    \"description\" : \"\",\n    \"required\" : false,\n    \"dataType\" : \"Object\",\n    \"type\" : null,\n    \"defaultValue\" : null,\n    \"validateType\" : \"\",\n    \"error\" : \"\",\n    \"expression\" : \"\",\n    \"children\" : [ {\n      \"name\" : \"status\",\n      \"value\" : \"200\",\n      \"description\" : \"\",\n      \"required\" : false,\n      \"data