     \"expression\" : \"\",\n      \"children\" : [ {\n        \"name\" : \"resultType\",\n        \"value\" : \"object\",\n        \"description\" : \"\",\n        \"required\" : false,\n        \"dataType\" : \"String\",\n        \"type\" : null,\n        \"defaultValue\" : null,\n        \"validateType\" : \"\",\n        \"error\" : \"\",\n        \"expression\" : \"\",\n        \"children\" : [ ]\n      }, {\n        \"name\" : \"result\",\n        \"value\" : \"\",\n        \"description\" : \"\",\n        \"required\" : false,\n        \"dataType\" : \"Object\",\n        \"type\" : null,\n        \"defaultValue\" : null,\n        \"validateType\" : \"\",\n        \"error\" : \"\",\n        \"expression\" : \"\",\n        \"children\" : [ ]\n      } ]\n    }, {\n      \"name\" : \"originalUrl\",\n      \"value\" : \"http://192.168.44.55:9999/?query=SELECT ip AS ip, SUM(client_sessions) AS client_sessions, SUM(server_sessions) AS server_sessions FROM( SELECT ip AS ip, IF(side = \'client\',SUM(common_sessions),0) AS client_sessions, IF(side = \'server\',SUM(common_sessions),0) AS server_sessions FROM metric_ip WHERE stat_time >= toDateTime(1673574154) AND stat_time < toDateTime(1673577754) AND ip = \'116.178.236.216\' GROUP BY ip,side ) GROUP BY ip&format=json&option=real-time\",\n      \"description\" : \"\",\n      \"required\" : false,\n      \"dataType\" : \"String\",\n      \"type\" : null,\n      \"defaultValue\" : null,\n      \"validateType\" : \"\",\n      \"error\" : \"\",\n      \"expression\" : \"\",\n      \"children\" : [ ]\n    }, {\n      \"name\" : \"msg\",\n      \"value\" : \"OK\",\n      \"description\" : \"\",\n      \"required\" : false,\n      \"dataType\" : \"String\",\n      \"type\" : null,\n      \"defaultValue\" : null,\n      \"validateType\" : \"\",\n      \"error\" : \"\",\n      \"expression\" : \"\",\n      \"children\" : [ ]\n    } ]\n  }\n}\r\n================================\r\nimport http;\r\nimport net.geedge.common.utils.FreeMarkerUtil as freeMarkerUtil;\r\nimport net.geedge.common.utils.JSONUtil as jsonUtil;\r\nimport \'@/pre/timeHandle\' as preHandle;\r\nimport \'@/public/toHump\' as toHump\r\nimport \'@/public/getGalaxyResult\' as getGalaxyResult\r\n/**\r\n * 入参整理 包括调用公共函数\r\n */\r\nvar parameter={\r\n    \"startTime\":startTime,\r\n    \"endTime\":endTime,\r\n    \"ip\":ip\r\n}\r\n\r\npreHandle(parameter);\r\n\r\n/**\r\n * 接口sql相关内容整理 通过freemarker模板生成最后执行语句\r\n */\r\nvar q = \"{\\\"query\\\":\\\"SELECT ip AS ip, SUM(client_sessions) AS client_sessions, SUM(server_sessions) AS server_sessions FROM( SELECT ip AS ip, IF(side = \'client\',SUM(common_sessions),0) AS client_sessions, IF(side = \'server\',SUM(common_sessions),0) AS server_sessions FROM metric_ip WHERE stat_time >= ${startTime} AND stat_time < ${endTime} AND ip = \'${ip}\' GROUP BY ip,side ) GROUP BY ip\\\",\\\"option\\\":\\\"real-time\\\",\\\"format\\\":\\\"json\\\"}\"\r\n\r\nvar result  = freeMarkerUtil.processTemplateIntoString(\"applicationPerformanceRelatedSessions\",q,parameter);\r\nvar param = jsonUtil.toBean(result,HashMap.class);\r\nvar result = getGalaxyResult(param);\r\n\r\n\r\n/**\r\n * 处理galaxy返回的数据结果 将新结果返回前端界面\r\n */\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"object\"\r\n	o.result={};\r\n	if(result.data.length > 0){\r\n		var pojo = result.data[0];\r\n		var tempObj= {};\r\n		for (key,value in pojo){\r\n			var tempKey = toHump(key);\r\n			tempObj[tempKey] = pojo[key];\r\n		}\r\n		tempObj.sessionsRate = ((tempObj.clientSessions.asDouble() + tempObj.serverSessions.asDouble())	/ parameter.timeDiff).toFixed(2);	\r\n        o.result = tempObj;\r\n	}\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n}\r\n\r\nreturn result;');
