sion\" : null,\n    \"children\" : null\n  }, {\n    \"name\" : \"q\",\n    \"value\" : \"server_super_admin_area=\'xinjing\'\",\n    \"description\" : null,\n    \"required\" : true,\n    \"dataType\" : \"String\",\n    \"type\" : null,\n    \"defaultValue\" : null,\n    \"validateType\" : null,\n    \"error\" : null,\n    \"expression\" : null,\n    \"children\" : null\n  } ],\n  \"options\" : [ ],\n  \"requestBody\" : \"\",\n  \"headers\" : [ ],\n  \"paths\" : [ ],\n  \"responseBody\" : \"{\\n    \\\"message\\\": \\\"Please log in to the system first\\\",\\n    \\\"code\\\": 518008,\\n    \\\"time\\\": 1695262044052\\n}\",\n  \"description\" : null,\n  \"requestBodyDefinition\" : null,\n  \"responseBodyDefinition\" : {\n    \"name\" : \"\",\n    \"value\" : \"\",\n    \"description\" : \"\",\n    \"required\" : false,\n    \"dataType\" : \"Object\",\n    \"type\" : null,\n    \"defaultValue\" : null,\n    \"validateType\" : \"\",\n    \"error\" : \"\",\n    \"expression\" : \"\",\n    \"children\" : [ {\n      \"name\" : \"message\",\n      \"value\" : \"Please log in to the system first\",\n      \"description\" : \"\",\n      \"required\" : false,\n      \"dataType\" : \"String\",\n      \"type\" : null,\n      \"defaultValue\" : null,\n      \"validateType\" : \"\",\n      \"error\" : \"\",\n      \"expression\" : \"\",\n      \"children\" : [ ]\n    }, {\n      \"name\" : \"code\",\n      \"value\" : \"518008\",\n      \"description\" : \"\",\n      \"required\" : false,\n      \"dataType\" : \"Integer\",\n      \"type\" : null,\n      \"defaultValue\" : null,\n      \"validateType\" : \"\",\n      \"error\" : \"\",\n      \"expression\" : \"\",\n      \"children\" : [ ]\n    }, {\n      \"name\" : \"time\",\n      \"value\" : \"1695262044052\",\n      \"description\" : \"\",\n      \"required\" : false,\n      \"dataType\" : \"Long\",\n      \"type\" : null,\n      \"defaultValue\" : null,\n      \"validateType\" : \"\",\n      \"error\" : \"\",\n      \"expression\" : \"\",\n      \"children\" : [ ]\n    } ]\n  }\n}\r\n================================\r\nimport http;\r\nimport net.geedge.common.utils.FreeMarkerUtil as freeMarkerUtil;\r\nimport net.geedge.common.utils.JSONUtil as jsonUtil;\r\nimport \'@/pre/timeHandle\' as preHandle;\r\nimport \'@/public/getGalaxyResult\' as getGalaxyResult\r\nimport \'@/pre/typeHandle3rd\' as typeHandle3rd\r\n\r\n/**\r\n * 入参整理 包括调用公共函数\r\n */\r\nvar parameter={\r\n    \"startTime\":startTime,\r\n    \"endTime\":endTime,\r\n    \"limit\":limit,\r\n    \"type\":type,\r\n    \"name\":name,\r\n	\"q\":q\r\n}\r\n\r\npreHandle(parameter);\r\ntypeHandle3rd(parameter);\r\n/**\r\n * 接口sql相关内容整理 通过freemarker模板生成最后执行语句\r\n */\r\nvar q = \"{\\\"query\\\":\\\"SELECT ${dimension} AS ${label} FROM session_record_cn WHERE common_recv_time >= ${startTime} AND common_recv_time < ${endTime}<#if type?default(\'\')?trim? length gt 0 && type!=\'qtype\' && type!=\'rcode\'> AND notEmpty(${dimension}) </#if> AND common_l7_protocol = \'DNS\' <#if q?default(\'\')?trim? length gt 0> AND (${q}) </#if> <#if filter?default(\'\')?trim? length gt 0>AND (${filter}) </#if> <#if name?default(\'\')?trim? length gt 0> AND ${label} like \'%${name}%\'</#if> GROUP BY ${label} ORDER BY SUM(common_s2c_byte_num + common_c2s_byte_num) DESC <#if limit?default(\'\')?trim? length gt 0> LIMIT ${limit} </#if>\\\",\\\"option\\\":\\\"real-time\\\",\\\"format\\\":\\\"json\\\"}\"\r\n\r\nvar result  = freeMarkerUtil.processTemplateIntoString(\"dnsOverviewDrilldownList\",q,parameter);\r\nvar param = jsonUtil.toBean(result,HashMap.class);\r\nvar result = getGalaxyResult(param);\r\n\r\n\r\n/**\r\n * 处理galaxy返回的数据结果 将新结果返回前端界面\r\n */\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"Object\";\r\n	o.result=result.data;\r\n	if(o.result.length > 0){\r\n		for(i,j in o.result){\r\n            var pojo = o.result[i];\r\n			var val = \'\';\r\n			for (key,value in pojo){    \r\n				val = pojo[key];\r\n			}\r\n			o.result[i] = val;\r\n        }\r\n	}\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n}\r\n\r\nreturn result;');
