ssion\" : \"\",\n      \"children\" : [ {\n        \"name\" : \"resultType\",\n        \"value\" : \"object\",\n        \"description\" : \"\",\n        \"required\" : false,\n        \"dataType\" : \"String\",\n        \"type\" : null,\n        \"defaultValue\" : null,\n        \"validateType\" : \"\",\n        \"error\" : \"\",\n        \"expression\" : \"\",\n        \"children\" : [ ]\n      }, {\n        \"name\" : \"result\",\n        \"value\" : \"\",\n        \"description\" : \"\",\n        \"required\" : false,\n        \"dataType\" : \"Array\",\n        \"type\" : null,\n        \"defaultValue\" : null,\n        \"validateType\" : \"\",\n        \"error\" : \"\",\n        \"expression\" : \"\",\n        \"children\" : [ ]\n      } ]\n    }, {\n      \"name\" : \"originalUrl\",\n      \"value\" : \"http://192.168.44.55:9999/?query=SELECT TIME_FLOOR_WITH_FILL(stat_time,\'PT1M\',\'zero\') AS stat_time, SUM(common_c2s_byte_num + common_s2c_byte_num) AS total_bytes, SUM(traffic_inbound_byte) AS inbound_bytes, SUM(traffic_outbound_byte) AS outbound_bytes, COUNT(*) AS query_num FROM metric_protocol WHERE stat_time >= 1693272384 AND stat_time < 1693299968 AND common_l7_protocol = \'DNS\' GROUP BY stat_time ORDER BY stat_time ASC&format=json&option=real-time\",\n      \"description\" : \"\",\n      \"required\" : false,\n      \"dataType\" : \"String\",\n      \"type\" : null,\n      \"defaultValue\" : null,\n      \"validateType\" : \"\",\n      \"error\" : \"\",\n      \"expression\" : \"\",\n      \"children\" : [ ]\n    }, {\n      \"name\" : \"msg\",\n      \"value\" : \"OK\",\n      \"description\" : \"\",\n      \"required\" : false,\n      \"dataType\" : \"String\",\n      \"type\" : null,\n      \"defaultValue\" : null,\n      \"validateType\" : \"\",\n      \"error\" : \"\",\n      \"expression\" : \"\",\n      \"children\" : [ ]\n    } ]\n  }\n}\r\n================================\r\nimport http;\r\nimport net.geedge.common.utils.FreeMarkerUtil as freeMarkerUtil;\r\nimport net.geedge.common.utils.JSONUtil as jsonUtil;\r\nimport \'@/pre/timeHandleNone\' as preHandle;\r\nimport \'@/post/object\' as objHandle\r\nimport \'@/public/getPercentile\' as getPercentile\r\nimport \'@/public/getGalaxyResult\' as getGalaxyResult\r\n\r\n/**\r\n * 入参整理 包括调用公共函数\r\n */\r\nvar parameter={\r\n    \"startTime\":startTime,\r\n    \"endTime\":endTime\r\n}\r\n\r\npreHandle(parameter);\r\n/**\r\n * 接口sql相关内容整理 通过freemarker模板生成最后执行语句\r\n */\r\nvar q = \"{\\\"query\\\":\\\"SELECT TIME_FLOOR_WITH_FILL(stat_time,\'PT${step}S\',\'zero\') AS stat_time, SUM(common_c2s_byte_num + common_s2c_byte_num) AS total_bytes, SUM(traffic_inbound_byte) AS inbound_bytes, SUM(traffic_outbound_byte) AS outbound_bytes, COUNT(*) AS query_num FROM metric_protocol WHERE stat_time >= ${startTime} AND stat_time < ${endTime} AND common_l7_protocol = \'DNS\' GROUP BY stat_time ORDER BY stat_time ASC\\\",\\\"option\\\":\\\"real-time\\\",\\\"format\\\":\\\"json\\\"}\"\r\n\r\nvar result  = freeMarkerUtil.processTemplateIntoString(\"dnsOverviewTotalTrafficAnalysis\",q,parameter);\r\nvar param = jsonUtil.toBean(result,HashMap.class);\r\nvar result = getGalaxyResult(param);\r\n\r\n/**\r\n * 处理galaxy返回的数据结果 将新结果返回前端界面\r\n */\r\nif(result.success){\r\n	var o = {};\r\n	o.resultType=\"object\";\r\n	var old = new ArrayList();\r\n	var list = result.data;\r\n	var newList = new ArrayList();\r\n	for(i,j in list){\r\n		newList.add(list[i]);\r\n	}\r\n	if(list.length > 0){\r\n		for(i,j in list){\r\n			var pojo = list[i];\r\n			var tempObj= {};\r\n			for (key,value in pojo){\r\n				if(key.indexOf(\"stat_time\") != -1){\r\n					tempObj[\'statTime\'] = pojo[key]\r\n				}else if(key.indexOf(\"total_bytes\") != -1){\r\n					tempObj[\'totalBitsRate\'] = (pojo[key].asDouble() / parameter.step).toFixed(2).asDouble() * 8\r\n				}else if(key.indexOf(\"inbound_bytes\") != -1){\r\n					tempObj[\'inboundBitsRate\'] = (pojo[key].asDouble() / parameter.step).toFixed(2).asDouble() * 8\r\n				}else if(key.indexOf(\"outbound_bytes\") != -1){\r\n					tempObj[\'outboundBitsRate\'] = (pojo[key].asDouble() / parameter.step).toFixed(2).asDouble() * 8\r\n				}else if(key == \'query_num\'){\r\n					tempObj[\'totalQueryRate\'] = (pojo[key].asDouble() / parameter.step).toFixed(2).asDouble()\r\n				}\r\n			}\r\n			list[i] = tempObj;\r\n			list[i].statTime = list[i].statTime;\r\n		}\r\n		var bytes = [];\r\n		var queries = [];\r\n		for(key,value in list[0]){\r\n			if(key.indexOf(\"Bits\") != -1){\r\n				bytes.push(key);\r\n			} else if(key.indexOf(\"Query\") != -1){\r\n				queries.push(key);\r\n			}\r\n		}\r\n		var map = new HashMap();\r\n		map.put(\"totalBitsRate\",\"total_bytes\");\r\n		map.put(\"inboundBitsRate\",\"inbound_bytes\");\r\n		map.put(\"outboundBitsRate\",\"outbound_bytes\");\r\n		map.put(\"totalQueryRate\",\"query_num\");\r\n		var type = {};\r\n		type.bytes = bytes;\r\n		type.queries = queries;\r\n		for(key,value in type){\r\n			var obj = {};\r\n			obj.type = key;\r\n			var typeKey = type[key];\r\n			for(m,n in typeKey){\r\n				var zong = {};\r\n				var analysis = {};\r\n				var values = new ArrayList();\r\n				list.sort((a,b)=>a.statTime.asDouble() - b.statTime.asDouble());\r\n				var sumValue = 0;\r\n				for(i,j in list){\r\n					var pojo = list[i];\r\n					var tempArray = new ArrayList();\r\n					tempArray.add(pojo[\"statTime\"]);\r\n					tempArray.add(pojo[typeKey[m]] + \"\");\r\n					values.add(tempArray);\r\n				}\r\n				for(i,j in newList){\r\n					var pojo = newList[i];\r\n					var field = map.get(typeKey[m]);\r\n					var value = pojo[field];\r\n					sumValue += value.asDouble();\r\n				}\r\n				analysis.avg =  (sumValue/parameter.timeDiff).toFixed(2);\r\n				if(key==\"bytes\"){\r\n					analysis.avg = analysis.avg.asDouble() * 8;\r\n				}\r\n				analysis.avg=analysis.avg+\"\";\r\n				\r\n				var plist = [];\r\n				for(i,j in values){\r\n					plist.push(values[i][1].asDouble());\r\n				}\r\n				analysis.max = plist.max()+\"\";\r\n				analysis.min = plist.min()+\"\";\r\n				analysis.p95 = getPercentile(plist, 0.95)+\"\";\r\n				\r\n                zong.values = values;\r\n				zong.analysis = analysis;\r\n				obj[typeKey[m]] = zong;\r\n			}\r\n			old.add(obj);\r\n		}\r\n	}\r\n	o.result = old;\r\n	result.code=200;\r\n 	result.data=o;\r\n 	result.msg = result.message;\r\n 	result.message=null;\r\n}\r\n\r\nreturn result;');
