672983936\\\", 0],\\n                [\\\"1672984800\\\", 0],\\n                [\\\"1672985664\\\", 0],\\n                [\\\"1672986528\\\", 0]\\n            ],\\n            \\\"legend\\\": \\\"36.155.23.177\\\",\\n            \\\"aggregation\\\": {\\n                \\\"first\\\": 0,\\n                \\\"last\\\": 0,\\n                \\\"avg\\\": \\\"0.0014\\\",\\n                \\\"p50\\\": 0,\\n                \\\"p90\\\": 0,\\n                \\\"max\\\": 0.1429\\n            }\\n        }]\\n    },\\n    \\\"msg\\\": \\\"OK\\\"\\n}\",\n  \"description\" : null,\n  \"requestBodyDefinition\" : null,\n  \"responseBodyDefinition\" : null\n}\r\n================================\r\nimport net.geedge.common.utils.FreeMarkerUtil as freeMarkerUtil;\r\nimport net.geedge.common.utils.JSONUtil as jsonUtil;\r\nimport \'@/pre/timeHandle\' as preHandle;\r\nimport \'@/post/qualityOfService\' as postHandle;\r\nimport \'@/public/getGalaxyResult\' as getGalaxyResult;\r\n\r\n/**\r\n * 入参整理 包括调用公共函数\r\n */\r\nvar parameter={\r\n    \"appName\":appName,\r\n    \"startTime\":startTime,\r\n    \"endTime\":endTime\r\n}\r\npreHandle(parameter);\r\n/**\r\n * 接口sql相关内容整理 通过freemarker模板生成最后执行语句\r\n */\r\nvar q = \"{\\r\\n    \\\"query\\\": \\\"SELECT TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(common_recv_time),\\\'PT${step}S\\\',\\\'zero\\\') as stat_time, common_client_ip AS common_client_ip, ROUND(AVG((common_c2s_pkt_retrans + common_s2c_pkt_retrans)/(common_c2s_pkt_num + common_s2c_pkt_num)),4) AS pkt_retrans_percent FROM session_record_cn WHERE common_recv_time >= ${startTime} AND common_recv_time < ${endTime} AND common_client_ip in ( SELECT common_client_ip FROM session_record_cn WHERE common_recv_time >= ${startTime} AND common_recv_time < ${endTime} AND common_app_label = \\\'${appName}\\\' AND notEmpty(common_client_ip) GROUP BY common_client_ip ORDER BY AVG((common_c2s_pkt_retrans + common_s2c_pkt_retrans)/(common_c2s_pkt_num + common_s2c_pkt_num)) DESC LIMIT 10 ) GROUP BY stat_time,common_client_ip\\\",\\r\\n    \\\"option\\\": \\\"real-time\\\",\\r\\n    \\\"format\\\": \\\"json\\\"\\r\\n}\"\r\nvar result  = freeMarkerUtil.processTemplateIntoString(\"entityDetailAppClientIpPacketRetrans\",q,parameter);\r\n\r\n/**\r\n * 调用galaxy接口获取结果信息\r\n */\r\nvar res = jsonUtil.toBean(result,HashMap.class);\r\nvar galaxyRes = getGalaxyResult(res);\r\n\r\n/**\r\n * 处理galaxy返回的数据结果 将新结果返回前端界面\r\n */\r\nvar result = postHandle(galaxyRes,\"commonClientIp\",\"pktRetransPercent\");\r\nprintln(jsonUtil.toJsonStr(galaxyRes));\r\n\r\nreturn result;');
