========================\r\nimport net.geedge.common.utils.FreeMarkerUtil as freeMarkerUtil;\r\nimport net.geedge.common.utils.JSONUtil as jsonUtil;\r\nimport \'@/pre/timeHandle\' as preHandle;\r\nimport \'@/post/mapHandleV2309\' as postHandle;\r\nimport \'@/public/getGalaxyResult\' as getGalaxyResult;\r\nimport \'@/public/toHump\' as toHump\r\n\r\n/**\r\n * 入参整理 包括调用公共函数\r\n */\r\nvar parameter={\r\n    \"ip\":ip,\r\n    \"startTime\":startTime,\r\n    \"endTime\":endTime,\r\n    \"country\":countryRegion,\r\n    \"province\":superAdminArea\r\n}\r\npreHandle(parameter);\r\n/**\r\n * 接口sql相关内容整理 通过freemarker模板生成最后执行语句\r\n */\r\nvar q = \"{\\r\\n    \\\"query\\\": \\\"SELECT server_country_region AS server_country_region,  <#if country?default(\\\'\\\')?trim? length gt 0> server_super_admin_area AS server_super_admin_area, <#if province?default(\\\'\\\')?trim? length gt 0> server_admin_area AS server_admin_area, </#if> </#if>     SUM(common_c2s_byte_num + common_s2c_byte_num) AS bytes,SUM(common_c2s_byte_num) AS sent_bytes, SUM(common_s2c_byte_num) AS received_bytes,SUM(common_c2s_pkt_num + common_s2c_pkt_num) AS packets,     SUM(common_sessions) as sessions FROM     session_record_cn WHERE     common_recv_time >= ${startTime}     AND common_recv_time < ${endTime} 	AND  common_server_ip   = \\\'${ip}\\\'  	<#if country?default(\\\'\\\')?trim? length gt 0> <#if province?default(\\\'\\\')?trim? length gt 0>AND server_country_region = \\\'${country}\\\'  AND server_super_admin_area = \\\'${province}\\\' AND server_admin_area != \\\'\\\' <#else> AND server_country_region = \\\'${country}\\\' AND server_super_admin_area != \\\'\\\' </#if> <#else> AND server_country_region != \\\'\\\' </#if> GROUP BY server_country_region <#if country?default(\\\'\\\')?trim? length gt 0>,server_super_admin_area <#if province?default(\\\'\\\')?trim? length gt 0>,server_admin_area</#if></#if>\\\",\\r\\n    \\\"option\\\": \\\"real-time\\\",\\r\\n    \\\"format\\\": \\\"json\\\"\\r\\n}\"\r\nvar result  = freeMarkerUtil.processTemplateIntoString(\"entityDetailIpTrafficMap\",q,parameter);\r\n\r\n/**\r\n * 调用galaxy接口获取结果信息\r\n */\r\nvar res = jsonUtil.toBean(result,HashMap.class);\r\nvar galaxyRes = getGalaxyResult(res);\r\n\r\n/**\r\n * 处理galaxy返回的数据结果 将新结果返回前端界面\r\n */\r\nvar result = postHandle(galaxyRes);\r\nprintln(jsonUtil.toJsonStr(result));\r\n\r\nreturn result;');
