,\\n                [\\\"1672932960\\\", 0],\\n                [\\\"1672933824\\\", 0],\\n                [\\\"1672934688\\\", 0],\\n                [\\\"1672935552\\\", 0],\\n                [\\\"1672936416\\\", 0],\\n                [\\\"1672937280\\\", 0.0612],\\n                [\\\"1672938144\\\", 0],\\n                [\\\"1672939008\\\", 0],\\n                [\\\"1672939872\\\", 0],\\n                [\\\"1672940736\\\", 0],\\n                [\\\"1672941600\\\", 0],\\n                [\\\"1672942464\\\", 0],\\n                [\\\"1672943328\\\", 0],\\n                [\\\"1672944192\\\", 0],\\n                [\\\"1672945056\\\", 0],\\n                [\\\"1672945920\\\", 0],\\n                [\\\"1672946784\\\", 0],\\n                [\\\"1672947648\\\", 0],\\n                [\\\"1672948512\\\", 0],\\n                [\\\"1672949376\\\", 0],\\n                [\\\"1672950240\\\", 0],\\n                [\\\"1672951104\\\", 0],\\n                [\\\"1672951968\\\", 0],\\n                [\\\"1672952832\\\", 0],\\n                [\\\"1672953696\\\", 0],\\n                [\\\"1672954560\\\", 0],\\n                [\\\"1672955424\\\", 0],\\n                [\\\"1672956288\\\", 0],\\n                [\\\"1672957152\\\", 0.2683],\\n                [\\\"1672958016\\\", 0],\\n                [\\\"1672958880\\\", 0],\\n                [\\\"1672959744\\\", 0.2857],\\n                [\\\"1672960608\\\", 0],\\n                [\\\"1672961472\\\", 0],\\n                [\\\"1672962336\\\", 1.0E-4],\\n                [\\\"1672963200\\\", 0],\\n                [\\\"1672964064\\\", 0],\\n                [\\\"1672964928\\\", 0],\\n                [\\\"1672965792\\\", 0],\\n                [\\\"1672966656\\\", 0],\\n                [\\\"1672967520\\\", 0],\\n                [\\\"1672968384\\\", 0],\\n                [\\\"1672969248\\\", 0],\\n                [\\\"1672970112\\\", 0],\\n                [\\\"1672970976\\\", 0],\\n                [\\\"1672971840\\\", 0],\\n                [\\\"1672972704\\\", 0],\\n                [\\\"1672973568\\\", 0],\\n                [\\\"1672974432\\\", 0],\\n                [\\\"1672975296\\\", 0],\\n                [\\\"1672976160\\\", 0],\\n                [\\\"1672977024\\\", 0],\\n                [\\\"1672977888\\\", 0],\\n                [\\\"1672978752\\\", 0],\\n                [\\\"1672979616\\\", 0],\\n                [\\\"1672980480\\\", 0],\\n                [\\\"1672981344\\\", 0],\\n                [\\\"1672982208\\\", 0],\\n                [\\\"1672983072\\\", 0],\\n                [\\\"1672983936\\\", 0],\\n                [\\\"1672984800\\\", 0],\\n                [\\\"1672985664\\\", 0],\\n                [\\\"1672986528\\\", 0]\\n            ],\\n            \\\"legend\\\": \\\"apple_music\\\",\\n            \\\"aggregation\\\": {\\n                \\\"first\\\": 0,\\n                \\\"last\\\": 0,\\n                \\\"avg\\\": \\\"0.01\\\",\\n                \\\"p50\\\": 0,\\n                \\\"p90\\\": 0,\\n                \\\"max\\\": 0.2857\\n            }\\n        }]\\n    },\\n    \\\"msg\\\": \\\"OK\\\"\\n}\",\n  \"description\" : null,\n  \"requestBodyDefinition\" : null,\n  \"responseBodyDefinition\" : null\n}\r\n================================\r\nimport net.geedge.common.utils.FreeMarkerUtil as freeMarkerUtil;\r\nimport net.geedge.common.utils.JSONUtil as jsonUtil;\r\nimport \'@/pre/timeHandle\' as preHandle;\r\nimport \'@/post/table\' as postHandle;\r\nimport \'@/public/getGalaxyResult\' as getGalaxyResult;\r\n\r\n/**\r\n * 入参整理 包括调用公共函数\r\n */\r\nvar parameter={\r\n    \"ip\":ip,\r\n    \"startTime\":startTime,\r\n    \"endTime\":endTime\r\n}\r\npreHandle(parameter);\r\n/**\r\n * 接口sql相关内容整理 通过freemarker模板生成最后执行语句\r\n */\r\nvar q = \"{\\r\\n    \\\"query\\\": \\\"(SELECT common_in_link_id AS linkID,\\\'in\\\' as direction,SUM(common_c2s_byte_num + common_s2c_byte_num) AS bytes,ROUND(AVG(common_establish_latency_ms)) AS latency,ROUND(SUM(common_c2s_tcp_lostlen + common_s2c_tcp_lostlen)/ SUM(common_c2s_byte_num + common_s2c_byte_num + common_c2s_tcp_lostlen + common_s2c_tcp_lostlen), 4) AS lossPercent,ROUND(SUM(common_c2s_pkt_retrans + common_s2c_pkt_retrans)/ SUM(common_c2s_pkt_num + common_s2c_pkt_num), 4) AS retransPercent FROM session_record_cn WHERE common_recv_time >= ${startTime} AND common_recv_time < ${endTime} AND common_in_link_id != 0 AND common_out_link_id !=0 AND (common_server_ip = \\\'${ip}\\\' OR common_client_ip = \\\'${ip}\\\') GROUP BY linkID ORDER BY bytes DESC) UNION ALL (SELECT common_out_link_id AS linkID,\\\'out\\\' as direction,SUM(common_c2s_byte_num + common_s2c_byte_num) AS bytes,ROUND(AVG(common_establish_latency_ms)) AS latency,ROUND(SUM(common_c2s_tcp_lostlen + common_s2c_tcp_lostlen)/ SUM(common_c2s_byte_num + common_s2c_byte_num + common_c2s_tcp_lostlen + common_s2c_tcp_lostlen), 4) AS lossPercent,ROUND(SUM(common_c2s_pkt_retrans + common_s2c_pkt_retrans)/ SUM(common_c2s_pkt_num + common_s2c_pkt_num), 4) AS retransPercent FROM session_record_cn WHERE common_recv_time >= ${startTime} AND common_recv_time < ${endTime} AND common_in_link_id != 0 AND common_out_link_id !=0 AND (common_server_ip = \\\'${ip}\\\' OR common_client_ip = \\\'${ip}\\\') GROUP BY linkID ORDER BY bytes DESC)\\\",\\r\\n    \\\"option\\\": \\\"real-time\\\",\\r\\n    \\\"format\\\": \\\"json\\\"\\r\\n}\"\r\nvar result  = freeMarkerUtil.processTemplateIntoString(\"entityDetailIpLinkVisual\",q,parameter);\r\n\r\n/**\r\n * 调用galaxy接口获取结果信息\r\n */\r\nvar res = jsonUtil.toBean(result,HashMap.class);\r\nvar galaxyRes = getGalaxyResult(res);\r\n\r\n/**\r\n * 处理galaxy返回的数据结果 将新结果返回前端界面\r\n */\r\nvar result = postHandle(galaxyRes);\r\nprintln(jsonUtil.toJsonStr(galaxyRes));\r\n\r\nreturn result;');
