r\n * 接口sql相关内容整理 通过freemarker模板生成最后执行语句\r\n */\r\nvar q = \"{\\r\\n    \\\"query\\\": \\\"SELECT TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(stat_time),\'PT${step}S\',\'zero\') AS stat_time, ROUND(SUM(common_c2s_byte_num + common_s2c_byte_num) * 8/ ${step}) AS rate, ROUND(SUM(common_c2s_byte_num) * 8/ ${step}) AS sent_rate, ROUND(SUM(common_s2c_byte_num) * 8/ ${step}) AS received_rate FROM metric_domain WHERE stat_time >= ${startTime} AND stat_time < ${endTime} AND domain = \'${domain}\' GROUP BY stat_time\\\",\\r\\n    \\\"option\\\": \\\"real-time\\\",\\r\\n    \\\"format\\\": \\\"json\\\"\\r\\n}\"\r\nvar result  = freeMarkerUtil.processTemplateIntoString(\"entityDetailOverviewDomainTraffic\",q,parameter);\r\n\r\n/**\r\n * 调用galaxy接口获取结果信息\r\n */\r\nvar res = jsonUtil.toBean(result,HashMap.class);\r\nvar galaxyRes = getGalaxyResult(res);\r\n\r\n/**\r\n * 处理galaxy返回的数据结果 将新结果返回前端界面\r\n */\r\nvar result = postHandle(galaxyRes);\r\nprintln(jsonUtil.toJsonStr(galaxyRes));\r\n\r\nreturn result;');
