n      \"expression\" : \"\",\n      \"children\" : [ ]\n    } ]\n  }\n}\r\n================================\r\nimport net.geedge.common.utils.FreeMarkerUtil as freeMarkerUtil;\r\nimport net.geedge.common.utils.JSONUtil as jsonUtil;\r\nimport \'@/pre/timeHandleNone\' as preHandle;\r\nimport \'@/post/object\' as postHandle;\r\nimport \'@/public/getGalaxyResult\' as getGalaxyResult;\r\nimport \'@get:/interface/entity/detail/overview/domain/networkQuantity/145\' as networkQuantity1;\r\nimport \'@get:/interface/entity/detail/overview/domain/networkQuantity/2\' as networkQuantity2;\r\nimport \'@get:/interface/entity/detail/overview/domain/networkQuantity/3\' as networkQuantity3;\r\n\r\n/**\r\n * 入参整理 包括调用公共函数\r\n */\r\nvar parameter={\r\n    \"domain\":domain,\r\n    \"startTime\":startTime,\r\n    \"endTime\":endTime\r\n}\r\npreHandle(parameter);\r\nvar data1 = networkQuantity1(ip,startTime,endTime);\r\nvar data2 = networkQuantity2(ip,startTime,endTime);\r\nvar data3 = networkQuantity3(ip,startTime,endTime);\r\nif(data1.success){\r\n    if(!is_null(data1.data.result.establishLatencyValue)){\r\n        parameter.establishLatency = data1.data.result.establishLatencyValue+\"\";\r\n    } else {\r\n        parameter.establishLatency = \'null\';\r\n    }\r\n    if(!is_null(data1.data.result.establishLatencyP50)){\r\n        parameter.establishP50 = data1.data.result.establishLatencyP50+\"\";\r\n    } else {\r\n        parameter.establishP50 = \'null\';\r\n    }\r\n    if(!is_null(data1.data.result.establishLatencyP90)){\r\n        parameter.establishP90 = data1.data.result.establishLatencyP90+\"\";\r\n    } else {\r\n        parameter.establishP90 = \'null\';\r\n    }\r\n    if(!is_null(data1.data.result.establishLatencyP99)){\r\n        parameter.establishP99 = data1.data.result.establishLatencyP99+\"\";\r\n    } else {\r\n        parameter.establishP99 = \'null\';\r\n    }\r\n    if(!is_null(data1.data.result.sequenceGapLossPercentValue)){\r\n        parameter.sequenceGapLossPercent = data1.data.result.sequenceGapLossPercentValue+\"\";\r\n    } else {\r\n        parameter.sequenceGapLossPercent = \'null\';\r\n    }\r\n    if(!is_null(data1.data.result.sequenceGapLossPercentP50)){\r\n        parameter.sequenceP50 = data1.data.result.sequenceGapLossPercentP50+\"\";\r\n    } else {\r\n        parameter.sequenceP50 = \'null\';\r\n    }\r\n    if(!is_null(data1.data.result.sequenceGapLossPercentP90)){\r\n        parameter.sequenceP90 = data1.data.result.sequenceGapLossPercentP90+\"\";\r\n    } else {\r\n        parameter.sequenceP90 = \'null\';\r\n    }\r\n    if(!is_null(data1.data.result.sequenceGapLossPercentP99)){\r\n        parameter.sequenceP99 = data1.data.result.sequenceGapLossPercentP99+\"\";\r\n    } else {\r\n        parameter.sequenceP99 = \'null\';\r\n    }\r\n    if(!is_null(data1.data.result.pktRetransPercentValue)){\r\n        parameter.pktRetransPercent = data1.data.result.pktRetransPercentValue+\"\";\r\n    } else {\r\n        parameter.pktRetransPercent = \'null\';\r\n    }\r\n    if(!is_null(data1.data.result.pktRetransPercentP50)){\r\n        parameter.pktP50 = data1.data.result.pktRetransPercentP50+\"\";\r\n    } else {\r\n        parameter.pktP50 = \'null\';\r\n    }\r\n    if(!is_null(data1.data.result.pktRetransPercentP90)){\r\n        parameter.pktP90 = data1.data.result.pktRetransPercentP90+\"\";\r\n    } else {\r\n        parameter.pktP90 = \'null\';\r\n    }\r\n    if(!is_null(data1.data.result.pktRetransPercentP99)){\r\n        parameter.pktP99 = data1.data.result.pktRetransPercentP99+\"\";\r\n    } else {\r\n        parameter.pktP99 = \'null\';\r\n    }\r\n}\r\nif(data2.success){\r\n    if(!is_null(data2.data.result.httpResponseLatencyValue)){\r\n        parameter.httpResponseLatency = data2.data.result.httpResponseLatencyValue+\"\";\r\n    } else {\r\n        parameter.httpResponseLatency = \'null\';\r\n    }\r\n    if(!is_null(data2.data.result.httpResponseLatencyP50)){\r\n        parameter.httpP50 = data2.data.result.httpResponseLatencyP50+\"\";\r\n    } else {\r\n        parameter.httpP50 = \'null\';\r\n    }\r\n    if(!is_null(data2.data.result.httpResponseLatencyP90)){\r\n        parameter.httpP90 = data2.data.result.httpResponseLatencyP90+\"\";\r\n    } else {\r\n        parameter.httpP90 = \'null\';\r\n    }\r\n    if(!is_null(data2.data.result.httpResponseLatencyP99)){\r\n        parameter.httpP99 = data2.data.result.httpResponseLatencyP99+\"\";\r\n    } else {\r\n        parameter.httpP99 = \'null\';\r\n    }\r\n}\r\nif(data3.success){\r\n    if(!is_null(data3.data.result.sslConLatencyValue)){\r\n        parameter.sslConLatency = data3.data.result.sslConLatencyValue+\"\";\r\n    } else {\r\n        parameter.sslConLatency = \'null\';\r\n    }\r\n    if(!is_null(data3.data.result.sslConLatencyP50)){\r\n        parameter.sslP50 = data3.data.result.sslConLatencyP50+\"\";\r\n    } else {\r\n        parameter.sslP50 = \'null\';\r\n    }\r\n    if(!is_null(data3.data.result.sslConLatencyP90)){\r\n        parameter.sslP90 = data3.data.result.sslConLatencyP90+\"\";\r\n    } else {\r\n        parameter.sslP90 = \'null\';\r\n    }\r\n    if(!is_null(data3.data.result.sslConLatencyP99)){\r\n        parameter.sslP99 = data3.data.result.sslConLatencyP99+\"\";\r\n    } else {\r\n        parameter.sslP99 = \'null\';\r\n    }\r\n}\r\n/**\r\n * 接口sql相关内容整理 通过freemarker模板生成最后执行语句\r\n */\r\nvar q = \"{\\r\\n    \\\"query\\\": \\\"SELECT ${httpResponseLatency} AS http_response_latency_value, ${httpP50} AS http_response_latency_p50, ${httpP90} AS http_response_latency_p90, ${httpP99} AS http_response_latency_p99, ${sslConLatency} AS ssl_con_latency_value, ${sslP50} AS ssl_con_latency_p50, ${sslP90} AS ssl_con_latency_p90, ${sslP99} AS ssl_con_latency_p99, ${establishLatency} AS establish_latency_value, ${establishP50} AS establish_latency_p50, ${establishP90} AS establish_latency_p90, ${establishP99} AS establish_latency_p99, ${sequenceGapLossPercent} AS sequence_gap_loss_percent_value, ${sequenceP50} AS sequence_gap_loss_percent_p50, ${sequenceP90} AS sequence_gap_loss_percent_p90, ${sequenceP99} AS sequence_gap_loss_percent_p99, ${pktRetransPercent} AS pkt_retrans_percent_value, ${pktP50} AS pkt_retrans_percent_p50, ${pktP90} AS pkt_retrans_percent_p90, ${pktP99} AS pkt_retrans_percent_p99 FROM session_record_cn WHERE common_recv_time >= ${startTime} AND common_recv_time < ${endTime} AND domain = \\\'${domain}\\\' LIMIT 1\\\",\\r\\n    \\\"option\\\": \\\"real-time\\\",\\r\\n    \\\"format\\\": \\\"json\\\"\\r\\n}\"\r\nvar result  = freeMarkerUtil.processTemplateIntoString(\"entityDetailOverviewDomainNetworkQuantity\",q,parameter);\r\n\r\n/**\r\n * 调用galaxy接口获取结果信息\r\n */\r\nvar res = jsonUtil.toBean(result,HashMap.class);\r\nvar galaxyRes = getGalaxyResult(res);\r\n\r\n/**\r\n * 处理galaxy返回的数据结果 将新结果返回前端界面\r\n */\r\nvar result = postHandle(galaxyRes);\r\nprintln(jsonUtil.toJsonStr(galaxyRes));\r\n\r\nreturn result;');
