ssion\" : \"\",\n          \"children\" : [ ]\n        }, {\n          \"name\" : \"establishLatencyMs\",\n          \"value\" : \"90\",\n          \"description\" : \"\",\n          \"required\" : false,\n          \"dataType\" : \"Integer\",\n          \"type\" : null,\n          \"defaultValue\" : null,\n          \"validateType\" : \"\",\n          \"error\" : \"\",\n          \"expression\" : \"\",\n          \"children\" : [ ]\n        }, {\n          \"name\" : \"tcpLostlenPercent\",\n          \"value\" : \"0.0021\",\n          \"description\" : \"\",\n          \"required\" : false,\n          \"dataType\" : \"Double\",\n          \"type\" : null,\n          \"defaultValue\" : null,\n          \"validateType\" : \"\",\n          \"error\" : \"\",\n          \"expression\" : \"\",\n          \"children\" : [ ]\n        }, {\n          \"name\" : \"pktRetransPercent\",\n          \"value\" : \"0.0301\",\n          \"description\" : \"\",\n          \"required\" : false,\n          \"dataType\" : \"Double\",\n          \"type\" : null,\n          \"defaultValue\" : null,\n          \"validateType\" : \"\",\n          \"error\" : \"\",\n          \"expression\" : \"\",\n          \"children\" : [ ]\n        } ]\n      } ]\n    }, {\n      \"name\" : \"msg\",\n      \"value\" : \"OK\",\n      \"description\" : \"\",\n      \"required\" : false,\n      \"dataType\" : \"String\",\n      \"type\" : null,\n      \"defaultValue\" : null,\n      \"validateType\" : \"\",\n      \"error\" : \"\",\n      \"expression\" : \"\",\n      \"children\" : [ ]\n    } ]\n  }\n}\r\n================================\r\nimport http;\r\nimport net.geedge.common.utils.FreeMarkerUtil as freeMarkerUtil;\r\nimport net.geedge.common.utils.JSONUtil as jsonUtil;\r\nimport \'@/pre/timeHandle\' as preHandle;\r\nimport \'@/post/table\' as objHandle\r\nimport \'@/public/getGalaxyResult\' as getGalaxyResult\r\nimport \'@/pre/typeHandle2nd\' as type2Handle;\r\n/**\r\n * 入参整理 包括调用公共函数\r\n */\r\nvar parameter={\r\n    \"startTime\":startTime,\r\n    \"endTime\":endTime,\r\n    \"params\":params,\r\n    \"q\":q,\r\n    \"type\":type,\r\n    \"cycle\":cycle\r\n}\r\n\r\npreHandle(parameter);\r\ntype2Handle(parameter);\r\n\r\n/**\r\n * 接口sql相关内容整理 通过freemarker模板生成最后执行语句\r\n */\r\nvar q = \"{\\\"query\\\":\\\"<#if cycle?default(\'\')?trim? length gt 0 && cycle == 1>SELECT ${dimension} AS ${label},ROUND(AVG(common_establish_latency_ms)) AS establish_latency_ms,ROUND(SUM(common_c2s_tcp_lostlen + common_s2c_tcp_lostlen)/SUM(common_c2s_byte_num + common_s2c_byte_num + common_c2s_tcp_lostlen + common_s2c_tcp_lostlen),4) AS tcp_lostlen_percent,ROUND(SUM(common_c2s_pkt_retrans + common_s2c_pkt_retrans)/ SUM(common_c2s_pkt_num + common_s2c_pkt_num),4) AS pkt_retrans_percent FROM session_record_cn WHERE common_recv_time >= ${startTime}-${timeDiff} AND common_recv_time < ${endTime}-${timeDiff} AND common_l4_protocol IN (\'IPv4_TCP\', \'IPv6_TCP\') AND ${label} IN (<#if params?default(\'\')?trim? length gt 0> ${params} </#if>) <#if q?default(\'\')?trim? length gt 0> AND (${q}) </#if> GROUP BY ${label} <#else> SELECT ${dimension} AS ${label},ROUND(AVG(common_establish_latency_ms)) AS establish_latency_ms,ROUND(SUM(common_c2s_tcp_lostlen + common_s2c_tcp_lostlen)/SUM(common_c2s_byte_num + common_s2c_byte_num + common_c2s_tcp_lostlen + common_s2c_tcp_lostlen),4) AS tcp_lostlen_percent,ROUND(SUM(common_c2s_pkt_retrans + common_s2c_pkt_retrans)/ SUM(common_c2s_pkt_num + common_s2c_pkt_num),4) AS pkt_retrans_percent FROM session_record_cn WHERE common_recv_time >= ${startTime} AND common_recv_time < ${endTime} AND common_l4_protocol IN (\'IPv4_TCP\', \'IPv6_TCP\') AND ${label} IN (<#if params?default(\'\')?trim? length gt 0> ${params} </#if>) <#if q?default(\'\')?trim? length gt 0> AND (${q}) </#if> GROUP BY ${label} </#if>\\\",\\\"option\\\":\\\"real-time\\\",\\\"format\\\":\\\"json\\\"}\"\r\n\r\nvar result  = freeMarkerUtil.processTemplateIntoString(\"linkOverviewDrilldownDimensionNetworkAnalysis\",q,parameter);\r\nvar param = jsonUtil.toBean(result,HashMap.class);\r\nvar galaxyRes = getGalaxyResult(param);\r\n\r\n\r\n/**\r\n * 处理galaxy返回的数据结果 将新结果返回前端界面\r\n */\r\nvar result = objHandle(galaxyRes);\r\n\r\nreturn result;');
