  \"children\" : [ ]\n              }, {\n                \"name\" : \"min\",\n                \"value\" : \"0.0\",\n                \"description\" : \"\",\n                \"required\" : false,\n                \"dataType\" : \"Double\",\n                \"type\" : null,\n                \"defaultValue\" : null,\n                \"validateType\" : \"\",\n                \"error\" : \"\",\n                \"expression\" : \"\",\n                \"children\" : [ ]\n              }, {\n                \"name\" : \"p95\",\n                \"value\" : \"0.0\",\n                \"description\" : \"\",\n                \"required\" : false,\n                \"dataType\" : \"Double\",\n                \"type\" : null,\n                \"defaultValue\" : null,\n                \"validateType\" : \"\",\n                \"error\" : \"\",\n                \"expression\" : \"\",\n                \"children\" : [ ]\n              } ]\n            } ]\n          }, {\n            \"name\" : \"totalBitsRate\",\n            \"value\" : \"\",\n            \"description\" : \"\",\n            \"required\" : false,\n            \"dataType\" : \"Object\",\n            \"type\" : null,\n            \"defaultValue\" : null,\n            \"validateType\" : \"\",\n            \"error\" : \"\",\n            \"expression\" : \"\",\n            \"children\" : [ {\n              \"name\" : \"values\",\n              \"value\" : \"\",\n              \"description\" : \"\",\n              \"required\" : false,\n              \"dataType\" : \"Array\",\n              \"type\" : null,\n              \"defaultValue\" : null,\n              \"validateType\" : \"\",\n              \"error\" : \"\",\n              \"expression\" : \"\",\n              \"children\" : [ {\n                \"name\" : \"\",\n                \"value\" : \"\",\n                \"description\" : \"\",\n                \"required\" : false,\n                \"dataType\" : \"Array\",\n                \"type\" : null,\n                \"defaultValue\" : null,\n                \"validateType\" : \"\",\n                \"error\" : \"\",\n                \"expression\" : \"\",\n                \"children\" : [ {\n                  \"name\" : \"\",\n                  \"value\" : \"1695173184\",\n                  \"description\" : \"\",\n                  \"required\" : false,\n                  \"dataType\" : \"Integer\",\n                  \"type\" : null,\n                  \"defaultValue\" : null,\n                  \"validateType\" : \"\",\n                  \"error\" : \"\",\n                  \"expression\" : \"\",\n                  \"children\" : [ ]\n                } ]\n              } ]\n            }, {\n              \"name\" : \"analysis\",\n              \"value\" : \"\",\n              \"description\" : \"\",\n              \"required\" : false,\n              \"dataType\" : \"Object\",\n              \"type\" : null,\n              \"defaultValue\" : null,\n              \"validateType\" : \"\",\n              \"error\" : \"\",\n              \"expression\" : \"\",\n              \"children\" : [ {\n                \"name\" : \"avg\",\n                \"value\" : \"0.29\",\n                \"description\" : \"\",\n                \"required\" : false,\n                \"dataType\" : \"Double\",\n                \"type\" : null,\n                \"defaultValue\" : null,\n                \"validateType\" : \"\",\n                \"error\" : \"\",\n                \"expression\" : \"\",\n                \"children\" : [ ]\n              }, {\n                \"name\" : \"max\",\n                \"value\" : \"28.88\",\n                \"description\" : \"\",\n                \"required\" : false,\n                \"dataType\" : \"Double\",\n                \"type\" : null,\n                \"defaultValue\" : null,\n                \"validateType\" : \"\",\n                \"error\" : \"\",\n                \"expression\" : \"\",\n                \"children\" : [ ]\n              }, {\n                \"name\" : \"min\",\n                \"value\" : \"0.0\",\n                \"description\" : \"\",\n                \"required\" : false,\n                \"dataType\" : \"Double\",\n                \"type\" : null,\n                \"defaultValue\" : null,\n                \"validateType\" : \"\",\n                \"error\" : \"\",\n                \"expression\" : \"\",\n                \"children\" : [ ]\n              }, {\n                \"name\" : \"p95\",\n                \"value\" : \"0.0\",\n                \"description\" : \"\",\n                \"required\" : false,\n                \"dataType\" : \"Double\",\n                \"type\" : null,\n                \"defaultValue\" : null,\n                \"validateType\" : \"\",\n                \"error\" : \"\",\n                \"expression\" : \"\",\n                \"children\" : [ ]\n              } ]\n            } ]\n          } ]\n        } ]\n      } ]\n    }, {\n      \"name\" : \"originalUrl\",\n      \"value\" : \"http://192.168.44.55:9999/?query=SELECT TIME_FLOOR_WITH_FILL(stat_time,\'PT1728S\',\'zero\') AS stat_time,SUM(IF( common_out_link_id = 1536, traffic_outbound_byte, 0)) AS out_bytes,SUM(IF( common_in_link_id = 1537, traffic_inbound_byte, 0)) AS in_bytes,SUM(IF( common_out_link_id = 1536, traffic_outbound_pkt, 0)) AS out_pkt,SUM(IF( common_in_link_id = 1537, traffic_inbound_pkt, 0)) AS in_pkt,(out_bytes + in_bytes) AS bytes_total,(out_pkt + in_pkt) AS packets_total FROM metric_link WHERE stat_time >= 1695174320 AND stat_time < 1695347120  GROUP BY stat_time ORDER BY bytes_total DESC &format=json&option=real-time\",\n      \"description\" : \"\",\n      \"required\" : false,\n      \"dataType\" : \"String\",\n      \"type\" : null,\n      \"defaultValue\" : null,\n      \"validateType\" : \"\",\n      \"error\" : \"\",\n      \"expression\" : \"\",\n      \"children\" : [ ]\n    }, {\n      \"name\" : \"msg\",\n      \"value\" : \"OK\",\n      \"description\" : \"\",\n      \"required\" : false,\n      \"dataType\" : \"String\",\n      \"type\" : null,\n      \"defaultValue\" : null,\n      \"validateType\" : \"\",\n      \"error\" : \"\",\n      \"expression\" : \"\",\n      \"children\" : [ ]\n    } ]\n  }\n}\r\n================================\r\nimport http;\r\nimport net.geedge.common.utils.FreeMarkerUtil as freeMarkerUtil;\r\nimport net.geedge.common.utils.JSONUtil as jsonUtil;\r\nimport \'@/pre/timeHandleNone\' as preHandle;\r\nimport \'@/post/object\' as objHandle\r\nimport \'@/public/getPercentile\' as getPercentile\r\nimport \'@/public/getGalaxyResult\' as getGalaxyResult\r\n/**\r\n * 入参整理 包括调用公共函数\r\n */\r\nvar parameter={\r\n    \"startTime\":startTime,\r\n    \"endTime\":endTime,\r\n    \"q\":q,\r\n    \"outParam\":outParam,\r\n    \"inParam\":inParam,\r\n    \"limit\":limit\r\n}\r\n\r\npreHandle(parameter);\r\n\r\n/**\r\n * 接口sql相关内容整理 通过freemarker模板生成最后执行语句\r\n */\r\nvar q = \"{\\\"query\\\":\\\"SELECT TIME_FLOOR_WITH_FILL(stat_time,\'PT${step}S\',\'zero\') AS stat_time,SUM(IF( ${outParam}, traffic_outbound_byte, 0)) AS out_bytes,SUM(IF( ${inParam}, traffic_inbound_byte, 0)) AS in_bytes,SUM(IF( ${outParam}, traffic_outbound_pkt, 0)) AS out_pkt,SUM(IF( ${inParam}, traffic_inbound_pkt, 0)) AS in_pkt,(out_bytes + in_bytes) AS bytes_total,(out_pkt + in_pkt) AS packets_total FROM metric_link WHERE stat_time >= ${startTime} AND stat_time < ${endTime} <#if q?default(\'\')?trim? length gt 0> AND (${q}) </#if> GROUP BY stat_time ORDER BY bytes_total DESC <#if limit?default(\'\')?trim? length gt 0> LIMIT ${limit} </#if>\\\",\\\"option\\\":\\\"real-time\\\",\\\"format\\\":\\\"json\\\"}\"\r\n\r\nvar result  = freeMarkerUtil.processTemplateIntoString(\"linkOverviewDrilldownTotalTrafficAnalysis\",q,parameter);\r\nvar param = jsonUtil.toBean(result,HashMap.class);\r\nvar result = getGalaxyResult(param);\r\n\r\n\r\n/**\r\n * 处理galaxy返回的数据结果 将新结果返回前端界面\r\n */\r\nif(result.success){\r\n	var o = {};\r\n	o.resultType=\"object\";\r\n	var old = new ArrayList();\r\n	var list = result.data;\r\n	var newList = new ArrayList();\r\n	for(i,j in list){\r\n		newList.add(list[i]);\r\n	}\r\n	if(list.length > 0){\r\n		for(i,j in list){\r\n			var pojo = list[i];\r\n			var tempObj= {};\r\n			for (key,value in pojo){\r\n				if(key.indexOf(\"stat_time\") != -1){\r\n						tempObj[\'stat_time\'] = pojo[key]\r\n					}else if(key.indexOf(\"bytes_total\") != -1){\r\n						tempObj[\'totalBitsRate\'] = (pojo[key].asDouble() / parameter.step).toFixed(2).asDouble() * 8\r\n					}else if(key.indexOf(\"in_bytes\") != -1){\r\n						tempObj[\'inBitsRate\'] = (pojo[key].asDouble() / parameter.step).toFixed(2).asDouble() * 8\r\n					}else if(key.indexOf(\"out_bytes\") != -1){\r\n						tempObj[\'outBitsRate\'] = (pojo[key].asDouble() / parameter.step).toFixed(2).asDouble() * 8\r\n					}else if(key == \'packets_total\'){\r\n						tempObj[\'totalPacketsRate\'] = (pojo[key].asDouble() / parameter.step).toFixed(2)\r\n					}else if(key == \'in_pkt\'){\r\n						tempObj[\'inPacketsRate\'] = (pojo[key].asDouble() / parameter.step).toFixed(2)\r\n					}else if(key == \'out_pkt\'){\r\n						tempObj[\'outPacketsRate\'] = (pojo[key].asDouble() / parameter.step).toFixed(2)\r\n					}\r\n				}\r\n			list[i] = tempObj;\r\n			list[i].statTime = list[i].statTime;\r\n		}\r\n		var bytes = [];\r\n		var packets = [];\r\n		for(key,value in list[0]){\r\n			if(key.indexOf(\"Bits\") != -1){\r\n				bytes.push(key);\r\n			} else if(key.indexOf(\"Packets\") != -1){\r\n				packets.push(key);\r\n			}\r\n		}\r\n		var map = new HashMap();\r\n		map.put(\"totalBitsRate\",\"bytes_total\");\r\n		map.put(\"inBitsRate\",\"in_bytes\");\r\n		map.put(\"outBitsRate\",\"out_bytes\");\r\n		map.put(\"totalPacketsRate\",\"packets_total\");\r\n		map.put(\"inPacketsRate\",\"in_pkt\");\r\n		map.put(\"outPacketsRate\",\"out_pkt\");\r\n		var type = {};\r\n		type.bytes = bytes;\r\n		type.packets = packets;\r\n		for(key,value in type){\r\n			var obj = {};\r\n			obj.type = key;\r\n			var typeKey = type[key];\r\n			for(m,n in typeKey){\r\n				var zong = {};\r\n				var analysis = {};\r\n				var values = new ArrayList();\r\n				list.sort((a,b)=>a.stat_time.asDouble()-b.stat_time.asDouble());\r\n				var sumValue = 0;\r\n				for(i,j in list){\r\n					var pojo = list[i];\r\n					var tempArray = new ArrayList();\r\n					tempArray.add(pojo[\"stat_time\"]);\r\n					tempArray.add(pojo[typeKey[m]] + \"\");\r\n					values.add(tempArray);\r\n				}\r\n				for(i,j in newList){\r\n					var pojo = newList[i];\r\n					var field = map.get(typeKey[m]);\r\n					var value = pojo[field];\r\n					sumValue += value.asDouble();\r\n				}\r\n				analysis.avg =  sumValue/parameter.timeDiff;\r\n				if(key==\"bytes\"){\r\n					analysis.avg = analysis.avg.asDouble() * 8;\r\n				}\r\n				analysis.avg=analysis.avg.toFixed(2);\r\n				var plist = [];\r\n				for(i,j in values){\r\n					plist.push(values[i][1].asDouble());\r\n				}\r\n				analysis.max = plist.max();\r\n				analysis.min = plist.min();\r\n				analysis.p95 = getPercentile(plist, 0.95);\r\n				\r\n				zong.values = values;\r\n				zong.analysis = analysis;\r\n				obj[typeKey[m]] = zong;\r\n			}\r\n			old.add(obj);\r\n		}\r\n	}\r\n	o.result = old;\r\n	result.code=200;\r\n 	result.data=o;\r\n 	result.msg = result.message;\r\n 	result.message=null;\r\n}\r\n\r\nreturn result;');
