{\n      \"name\" : \"msg\",\n      \"value\" : \"OK\",\n      \"description\" : \"\",\n      \"required\" : false,\n      \"dataType\" : \"String\",\n      \"type\" : null,\n      \"defaultValue\" : null,\n      \"validateType\" : \"\",\n      \"error\" : \"\",\n      \"expression\" : \"\",\n      \"children\" : [ ]\n    } ]\n  }\n}\r\n================================\r\nimport net.geedge.common.utils.FreeMarkerUtil as freeMarkerUtil;\r\nimport net.geedge.common.utils.JSONUtil as jsonUtil;\r\nimport \'@/pre/timeHandle\' as preHandle;\r\nimport \'@/post/qualityOfService\' as postHandle;\r\nimport \'@/public/getGalaxyResult\' as getGalaxyResult;\r\n\r\n/**\r\n * 入参整理 包括调用公共函数\r\n */\r\nvar parameter={\r\n    \"startTime\":startTime,\r\n    \"endTime\":endTime\r\n}\r\npreHandle(parameter);\r\n\r\n/**\r\n * 接口sql相关内容整理 通过freemarker模板生成最后执行语句\r\n */\r\nvar q = \"{\\r\\n    \\\"query\\\": \\\"SELECT TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(common_recv_time),\\\'PT${step}S\\\',\\\'zero\\\') AS stat_time, common_client_ip AS client_ip, ROUND(AVG(common_establish_latency_ms)) AS establish_latency FROM session_record_cn WHERE common_recv_time > ${startTime} AND common_recv_time < ${endTime} AND common_client_ip in ( SELECT common_client_ip FROM metric_top_entity WHERE common_recv_time > ${startTime} AND common_recv_time < ${endTime} AND group_by = \\\'common_client_ip\\\' AND order_by = \\\'establish_latency\\\' AND time_granularity = 60 GROUP BY common_client_ip ORDER BY AVG(common_establish_latency_ms) DESC LIMIT 10 ) GROUP BY stat_time, client_ip\\\",\\r\\n    \\\"option\\\": \\\"real-time\\\",\\r\\n    \\\"format\\\": \\\"json\\\"\\r\\n}\"\r\nvar result  = freeMarkerUtil.processTemplateIntoString(\"npmClientIPRrt\",q,parameter);\r\n\r\n/**\r\n * 调用galaxy接口获取结果信息\r\n */\r\nvar res = jsonUtil.toBean(result,HashMap.class);\r\nvar galaxyRes = getGalaxyResult(res);\r\n\r\n/**\r\n * 处理galaxy返回的数据结果 将新结果返回前端界面\r\n */\r\nvar result = postHandle(galaxyRes,\"clientIp\",\"establishLatency\");\r\nprintln(jsonUtil.toJsonStr(galaxyRes));\r\n\r\nreturn result;');
