 [ ]\n    } ]\n  }\n}\r\n================================\r\nimport http;\r\nimport net.geedge.common.utils.FreeMarkerUtil as freeMarkerUtil;\r\nimport net.geedge.common.utils.JSONUtil as jsonUtil;\r\nimport \'@/pre/timeHandle\' as preHandle;\r\nimport \'@/post/table\' as objHandle\r\nimport \'@/public/getGalaxyResult\' as getGalaxyResult\r\nimport \'@/pre/typeHandle6th\' as typeHandle6th\r\nimport \'@/public/toHump\' as toHump\r\n/**\r\n * 入参整理 包括调用公共函数\r\n */\r\nvar parameter={\r\n    \"startTime\":startTime,\r\n    \"endTime\":endTime,\r\n    \"type\":type,\r\n    \"params\":params\r\n}\r\n\r\npreHandle(parameter);\r\ntypeHandle6th(parameter);\r\n/**\r\n * 接口sql相关内容整理 通过freemarker模板生成最后执行语句\r\n */\r\nvar q = \"{\\\"query\\\":\\\"SELECT ${fieldName} AS ${lad},SUM(common_c2s_byte_num + common_s2c_byte_num) AS bytes,SUM(common_c2s_pkt_num + common_s2c_pkt_num) AS packets,SUM(common_sessions) AS sessions FROM ${tableName} WHERE stat_time >= ${startTime} - ${timeDiff} AND stat_time < ${endTime} - ${timeDiff} AND ${lad} IN (<#if params?default(\'\')?trim? length gt 0> ${params} </#if>) <#if filter?default(\'\')?trim? length gt 0> ${filter} </#if> GROUP BY ${lad}\\\",\\\"option\\\":\\\"real-time\\\",\\\"format\\\":\\\"json\\\"}\"\r\n\r\nvar result  = freeMarkerUtil.processTemplateIntoString(\"overviewDimensionCycleTrafficAnalysis\",q,parameter);\r\nvar param = jsonUtil.toBean(result,HashMap.class);\r\nvar result = getGalaxyResult(param);\r\n\r\n\r\n/**\r\n * 处理galaxy返回的数据结果 将新结果返回前端界面\r\n */\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"table\";\r\n	o.result=result.data;\r\n	if(o.result.length > 0){\r\n		for(i,j in o.result){\r\n            var pojo = o.result[i];\r\n			var tempObj = {};\r\n			for (key,value in pojo){    \r\n				var tempKey = toHump(key);\r\n				tempObj[tempKey] = pojo[key];\r\n				if(key.indexOf(\"bytes\") != -1){\r\n					tempObj[\'bitsRate\'] = (pojo[key].asDouble() / parameter.timeDiff).toFixed(2).asDouble() * 8\r\n				}else if(key.indexOf(\"packets\") != -1){\r\n					tempObj[\'packetsRate\'] = (pojo[key].asDouble() / parameter.timeDiff).toFixed(2)\r\n				}else if(key.indexOf(\"sessions\") != -1){\r\n					tempObj[\'sessionsRate\'] = (pojo[key].asDouble() / parameter.timeDiff).toFixed(2)\r\n				}\r\n			}\r\n			o.result[i] = tempObj;\r\n        }\r\n	}\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n}\r\n\r\nreturn result;');
