er);\r\n/**\r\n * 接口sql相关内容整理 通过freemarker模板生成最后执行语句\r\n */\r\nvar q = \"{\\r\\n    \\\"query\\\": \\\"SELECT event_id AS event_id, security_type AS security_type, domain AS domain, offender_ip AS offender_ip, victim_ip AS victim_ip, client_ip AS client_ip, server_ip AS server_ip, event_severity AS event_severity, malware_name AS malware_name, cryptomining_pool AS cryptomining_pool, start_time AS start_time, duration_ms AS duration_ms, end_time AS end_time FROM security_event WHERE start_time >= ${startTime} AND start_time < ${endTime} <#if entityType?default(\\\'\\\')?trim? length gt 0 && resource?default(\\\'\\\')?trim? length gt 0> <#if entityType==\\\"app\\\"> AND app_name=\\\'${resource}\\\' <#elseif entityType==\\\"domain\\\"> AND domain=\\\'${resource}\\\' <#elseif entityType==\\\"ip\\\"> AND (client_ip=\\\'${resource}\\\' or server_ip=\\\'${resource}\\\') </#if> </#if> ORDER BY start_time DESC <#if pageSize?default(\\\'\\\')?trim? length gt 0&&pageNo?default(\\\'\\\')?trim? length gt 0> LIMIT ${pageNo},${pageSize}</#if>\\\",\\r\\n    \\\"option\\\": \\\"real-time\\\",\\r\\n    \\\"format\\\": \\\"json\\\"\\r\\n}\"\r\n\r\nvar result  = freeMarkerUtil.processTemplateIntoString(\"v1EntityDetailEventSecurityEntityType\",q,parameter);\r\n\r\n/**\r\n * 调用galaxy接口获取结果信息\r\n */\r\nvar res = jsonUtil.toBean(result,HashMap.class);\r\nvar galaxyRes = getGalaxyResult(res);\r\n\r\n/**\r\n * 处理galaxy返回的数据结果 将新结果返回前端界面\r\n */\r\nvar result = postHandle(galaxyRes);\r\nresult.data.pageNo = ObjectUtil.isNotEmpty(pageNo) ? pageNo : 1;\r\nresult.data.pageSize = ObjectUtil.isNotEmpty(pageSize) ? pageSize : parameter.pageSize;\r\nresult.data.total = result.data.result.length;\r\nresult.msg = \"success\";\r\nprintln(jsonUtil.toJsonStr(result));\r\nreturn result;');
