]\n    } ]\n  }\n}\r\n================================\r\nimport http;\r\nimport net.geedge.common.utils.FreeMarkerUtil as freeMarkerUtil;\r\nimport net.geedge.common.utils.JSONUtil as jsonUtil;\r\nimport \'@/pre/timeHandleHalf\' as timeHandle;\r\nimport \'@/post/array\' as postHandle;\r\nimport \'@/public/postGalaxyResult\' as postGalaxyResult;\r\nimport \'@/public/toHump\' as toHump;\r\n/**\r\n * 入参整理 包括调用公共函数\r\n */\r\nvar parameter={\r\n    \"resource\":resource,\r\n    \"startTime\":startTime,\r\n    \"endTime\":endTime\r\n}\r\ntimeHandle(parameter);\r\n/**\r\n * 接口sql相关内容整理 通过freemarker模板生成最后执行语句\r\n */\r\nvar q = \"{\\r\\n    \\\"query\\\": \\\"SELECT port AS port, l7_protocol AS l7_protocol FROM cn_ip_dynamic_attribute WHERE update_time >= ${startTime} AND update_time < ${endTime} AND ip IN (<#list resource?split(\\\",\\\") as ip><#if !ip_has_next>\\\'${ip}\\\'<#else>\\\'${ip}\\\',</#if></#list>) GROUP BY port,l7_protocol ORDER BY MAX(update_time) DESC\\\",\\r\\n    \\\"option\\\": \\\"real-time\\\",\\r\\n    \\\"format\\\": \\\"json\\\"\\r\\n}\"\r\nvar result  = freeMarkerUtil.processTemplateIntoString(\"v1EntityDetailIpRelatePorts\",q,parameter);\r\n\r\nvar totalQ = \"{\\r\\n    \\\"query\\\": \\\"SELECT COUNT(DISTINCT(concat(port,\'/\',l7_protocol))) AS openPortCount FROM cn_ip_dynamic_attribute WHERE update_time >= ${startTime} AND update_time < ${endTime} AND ip IN (<#list resource?split(\\\",\\\") as ip><#if !ip_has_next>\\\'${ip}\\\'<#else>\\\'${ip}\\\',</#if></#list>) AND notEmpty(l7_protocol)\\\",\\r\\n    \\\"option\\\": \\\"real-time\\\",\\r\\n    \\\"format\\\": \\\"json\\\"\\r\\n}\"\r\nvar totalResult  = freeMarkerUtil.processTemplateIntoString(\"v1EntityDetailIpRelatePortsCount\",totalQ,parameter);\r\n/**\r\n * 调用galaxy接口获取结果信息\r\n */\r\nvar res = jsonUtil.toBean(result,HashMap.class);\r\nvar galaxyRes = postGalaxyResult(res);\r\n\r\nvar totalRes = jsonUtil.toBean(totalResult,HashMap.class);\r\nvar total = postGalaxyResult(totalRes);\r\n/**\r\n * 处理galaxy返回的数据结果 将新结果返回前端界面\r\n */\r\nvar result = postHandle(galaxyRes);\r\nresult.data.total = total.data.openPortCount.asInt();\r\nvar url = db.select(\"select cvalue from sys_config where ckey = \'galaxy_url\'\");\r\nresult.originalUrl = url.cvalue+res.query;\r\nresult.msg = \"success\";\r\nreturn result;');
