INSERT INTO `magic_api_file` VALUES ('/api/v1/entity/detail/traffic/throughput/流量趋势.ms', '{\r\n  \"properties\" : { },\r\n  \"id\" : \"d1d21bd26bb649419380c15c21140723\",\r\n  \"script\" : null,\r\n  \"groupId\" : \"124c5f5b0fc248dda8e292e4befb4121\",\r\n  \"name\" : \"流量趋势\",\r\n  \"createTime\" : null,\r\n  \"updateTime\" : 1697773328334,\r\n  \"lock\" : null,\r\n  \"createBy\" : null,\r\n  \"updateBy\" : \"admin\",\r\n  \"path\" : \"{entityType}\",\r\n  \"method\" : \"GET\",\r\n  \"parameters\" : [ {\r\n    \"name\" : \"resource\",\r\n    \"value\" : \"www.gravatar.com\",\r\n    \"description\" : null,\r\n    \"required\" : true,\r\n    \"dataType\" : \"String\",\r\n    \"type\" : null,\r\n    \"defaultValue\" : null,\r\n    \"validateType\" : null,\r\n    \"error\" : null,\r\n    \"expression\" : null,\r\n    \"children\" : null\r\n  }, {\r\n    \"name\" : \"startTime\",\r\n    \"value\" : \"1695693162\",\r\n    \"description\" : null,\r\n    \"required\" : true,\r\n    \"dataType\" : \"Long\",\r\n    \"type\" : null,\r\n    \"defaultValue\" : null,\r\n    \"validateType\" : null,\r\n    \"error\" : null,\r\n    \"expression\" : null,\r\n    \"children\" : null\r\n  }, {\r\n    \"name\" : \"endTime\",\r\n    \"value\" : \"1695696762\",\r\n    \"description\" : null,\r\n    \"required\" : true,\r\n    \"dataType\" : \"Long\",\r\n    \"type\" : null,\r\n    \"defaultValue\" : null,\r\n    \"validateType\" : null,\r\n    \"error\" : null,\r\n    \"expression\" : null,\r\n    \"children\" : null\r\n  } ],\r\n  \"options\" : [ ],\r\n  \"requestBody\" : \"\",\r\n  \"headers\" : [ {\r\n    \"name\" : \"cn-Authorization\",\r\n    \"value\" : \"cntest\",\r\n    \"description\" : null,\r\n    \"required\" : false,\r\n    \"dataType\" : \"String\",\r\n    \"type\" : null,\r\n    \"defaultValue\" : null,\r\n    \"validateType\" : null,\r\n    \"error\" : null,\r\n    \"expression\" : null,\r\n    \"children\" : null\r\n  } ],\r\n  \"paths\" : [ {\r\n    \"name\" : \"entityType\",\r\n    \"value\" : \"domain\",\r\n    \"description\" : null,\r\n    \"required\" : true,\r\n    \"dataType\" : \"String\",\r\n    \"type\" : null,\r\n    \"defaultValue\" : null,\r\n    \"validateType\" : null,\r\n    \"error\" : null,\r\n    \"expression\" : null,\r\n    \"children\" : null\r\n  } ],\r\n  \"responseBody\" : \"{\\n    \\\"message\\\": \\\"Please log in to the system first\\\",\\n    \\\"code\\\": 518008,\\n    \\\"time\\\": 1697773307848\\n}\",\r\n  \"description\" : null,\r\n  \"requestBodyDefinition\" : null,\r\n  \"responseBodyDefinition\" : {\r\n    \"name\" : \"\",\r\n    \"value\" : \"\",\r\n    \"description\" : \"\",\r\n    \"required\" : false,\r\n    \"dataType\" : \"Object\",\r\n    \"type\" : null,\r\n    \"defaultValue\" : null,\r\n    \"validateType\" : \"\",\r\n    \"error\" : \"\",\r\n    \"expression\" : \"\",\r\n    \"children\" : [ {\r\n      \"name\" : \"message\",\r\n      \"value\" : \"Please log in to the system first\",\r\n      \"description\" : \"\",\r\n      \"required\" : false,\r\n      \"dataType\" : \"Object\",\r\n      \"type\" : null,\r\n      \"defaultValue\" : null,\r\n      \"validateType\" : \"\",\r\n      \"error\" : \"\",\r\n      \"expression\" : \"\",\r\n      \"children\" : [ ]\r\n    }, {\r\n      \"name\" : \"code\",\r\n      \"value\" : \"518008\",\r\n      \"description\" : \"\",\r\n      \"required\" : false,\r\n      \"dataType\" : \"Integer\",\r\n      \"type\" : null,\r\n      \"defaultValue\" : null,\r\n      \"validateType\" : \"\",\r\n      \"error\" : \"\",\r\n      \"expression\" : \"\",\r\n      \"children\" : [ ]\r\n    }, {\r\n      \"name\" : \"time\",\r\n      \"value\" : \"1697773307848\",\r\n      \"description\" : \"\",\r\n      \"required\" : false,\r\n      \"dataType\" : \"Long\",\r\n      \"type\" : null,\r\n      \"defaultValue\" : null,\r\n      \"validateType\" : \"\",\r\n      \"error\" : \"\",\r\n      \"expression\" : \"\",\r\n      \"children\" : [ ]\r\n    } ]\r\n  }\r\n}\r\n================================\r\nimport http;\r\nimport net.geedge.common.utils.FreeMarkerUtil as freeMarkerUtil;\r\nimport net.geedge.common.utils.JSONUtil as jsonUtil;\r\nimport \'@/pre/timeHandle\' as preHandle;\r\nimport \'@/post/table\' as objHandle\r\nimport \'@/public/getGalaxyResult\' as getGalaxyResult\r\nimport \'@/public/getPercentile\' as getPercentile\r\n\r\n/**\r\n * 入参整理 包括调用公共函数\r\n */\r\nvar parameter={\r\n    \"startTime\":startTime,\r\n    \"endTime\":endTime,\r\n    \"resource\":resource,\r\n	\"entityType\":path.entityType\r\n}\r\n\r\npreHandle(parameter);\r\n\r\n\r\n/**\r\n * 接口sql相关内容整理 通过freemarker模板生成最后执行语句\r\n */\r\nvar q = \"{\\\"query\\\":\\\"SELECT TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(stat_time),\\\'PT${step}S\\\',\\\'zero\\\') AS granularity, SUM(common_s2c_byte_num + common_c2s_byte_num) AS total_bytes, SUM(common_s2c_pkt_num + common_c2s_pkt_num) AS total_packets, SUM(common_sessions) AS total_sessions, SUM(traffic_inbound_byte) AS inbound_bytes, SUM(traffic_inbound_pkt) AS inbound_packets, SUM(traffic_outbound_byte) AS outbound_bytes, SUM(traffic_outbound_pkt) AS outbound_packets, SUM(traffic_internal_byte) AS internal_bytes, SUM(traffic_internal_pkt) AS internal_packets, SUM(traffic_through_byte) AS through_bytes, SUM(traffic_through_pkt) AS through_packets FROM <#if entityType?default(\'\')?trim? length gt 0 && entityType==\'ip\'> metric_ip <#elseif entityType?default(\'\')?trim? length gt 0 && entityType==\'domain\'> metric_domain <#else> metric_application </#if> WHERE stat_time >= ${startTime} AND stat_time < ${endTime} <#if entityType?default(\'\')?trim? length gt 0 && entityType==\'ip\'> AND ip = \'${resource}\' AND side = \'server\' <#elseif entityType?default(\'\')?trim? length gt 0 && entityType==\'domain\'> AND domain = \'${resource}\' <#else> AND common_app_label = \'${resource}\' </#if> GROUP BY granularity ORDER BY granularity ASC\\\",\\\"option\\\":\\\"real-time\\\",\\\"format\\\":\\\"json\\\"}\"\r\n\r\nvar result  = freeMarkerUtil.processTemplateIntoString(\"v1EntityDetailTrafficThroughput\",q,parameter);\r\nvar param = jsonUtil.toBean(result,HashMap.class);\r\nvar result = getGalaxyResult(param);\r\n\r\n\r\n/**\r\n * 处理galaxy返回的数据结果 将新结果返回前端界面\r\n */\r\nif(result.success){\r\n	var o = {};\r\n	o.resultType=\"object\";\r\n	var old = new ArrayList();\r\n	var list = result.data;\r\n	var newList = new ArrayList();\r\n	for(i,j in list){\r\n		newList.add(list[i]);\r\n	}\r\n	if(list.length > 0){\r\n		for(i,j in list){\r\n			var pojo = list[i];\r\n			var tempObj= {};\r\n			for (key,value in pojo){\r\n				if(key.indexOf(\"granularity\") != -1){\r\n					tempObj[\'statTime\'] = pojo[key]\r\n				}else if(key.indexOf(\"total_bytes\") != -1){\r\n					tempObj[\'totalBitsRate\'] = (pojo[key].asDouble() / parameter.step).toFixed(2).asDouble() * 8\r\n				}else if(key.indexOf(\"total_packets\") != -1){\r\n					tempObj[\'totalPacketsRate\'] = (pojo[key].asDouble() / parameter.step).toFixed(2)\r\n				}else if(key.indexOf(\"total_sessions\") != -1){\r\n					tempObj[\'totalSessionsRate\'] = (pojo[key].asDouble() / parameter.step).toFixed(2)\r\n				}else if(key.indexOf(\"inbound_bytes\") != -1){\r\n					tempObj[\'inboundBitsRate\'] = (pojo[key].asDouble() / parameter.step).toFixed(2).asDouble() * 8\r\n				}else if(key.indexOf(\"inbound_packets\") != -1){\r\n					tempObj[\'inboundPacketsRate\'] = (pojo[key].asDouble() / parameter.step).toFixed(2)\r\n				}else if(key.indexOf(\"outbound_bytes\") != -1){\r\n					tempObj[\'outboundBitsRate\'] = (pojo[key].asDouble() / parameter.step).toFixed(2).asDouble() * 8\r\n				}else if(key.indexOf(\"outbound_packets\") != -1){\r\n					tempObj[\'outboundPacketsRate\'] = (pojo[key].asDouble() / parameter.step).toFixed(2)\r\n				}else if(key.indexOf(\"internal_bytes\") != -1){\r\n					tempObj[\'internalBitsRate\'] = (pojo[key].asDouble() / parameter.step).toFixed(2).asDouble() * 8\r\n				}else if(key.indexOf(\"internal_packets\") != -1){\r\n					tempObj[\'internalPacketsRate\'] = (pojo[key].asDouble() / parameter.step).toFixed(2)\r\n				}else if(key.indexOf(\"through_bytes\") != -1){\r\n					tempObj[\'throughBitsRate\'] = (pojo[key].asDouble() / parameter.step).toFixed(2).asDouble() * 8\r\n				}else if(key.indexOf(\"through_packets\") != -1){\r\n					tempObj[\'throughPacketsRate\'] = (pojo[key].asDouble() / parameter.step).toFixed(2)\r\n				}\r\n			}\r\n			list[i] = tempObj;\r\n		}\r\n		var bytes = [];\r\n		var packets = [];\r\n		var sessions = [];\r\n		var establishLatencyMs = [];\r\n		var httpResponseLatency = [];\r\n		var sslConLatency = [];\r\n		var tcpLostlenPercent = [];\r\n		var pktRetransPercent = [];\r\n		for(key,value in list[0]){\r\n			if(key.indexOf(\"Bits\") != -1){\r\n				bytes.push(key);\r\n			} else if(key.indexOf(\"Packets\") != -1){\r\n				packets.push(key);\r\n			} else if(key.indexOf(\"Sessions\") != -1){\r\n				sessions.push(key);\r\n			} else if(key.indexOf(\"establishLatencyMsAvg\") != -1){\r\n				establishLatencyMs.push(key);\r\n			} else if(key.indexOf(\"httpResponseLatencyAvg\") != -1){\r\n				httpResponseLatency.push(key);\r\n			} else if(key.indexOf(\"sslConLatencyAvg\") != -1){\r\n				sslConLatency.push(key);\r\n			} else if(key.indexOf(\"tcpLostlenPercentAvg\") != -1){\r\n				tcpLostlenPercent.push(key);\r\n			} else if(key.indexOf(\"pktRetransPercentAvg\") != -1){\r\n				pktRetransPercent.push(key);\r\n			}\r\n		}\r\n		var map = new HashMap();\r\n		map.put(\"totalBitsRate\",\"total_bytes\");\r\n		map.put(\"totalPacketsRate\",\"total_packets\");\r\n		map.put(\"totalSessionsRate\",\"total_sessions\");\r\n		map.put(\"inboundBitsRate\",\"inbound_bytes\");\r\n		map.put(\"inboundPacketsRate\",\"inbound_packets\");\r\n		map.put(\"outboundBitsRate\",\"outbound_bytes\");\r\n		map.put(\"outboundPacketsRate\",\"outbound_packets\");\r\n		map.put(\"internalBitsRate\",\"internal_bytes\");\r\n		map.put(\"internalPacketsRate\",\"internal_packets\");\r\n		map.put(\"throughBitsRate\",\"through_bytes\");\r\n		map.put(\"throughPacketsRate\",\"through_packets\");\r\n		var type = {};\r\n		type.bytes = bytes;\r\n		type.packets = packets;\r\n		type.sessions = sessions;\r\n		for(key,value in type){\r\n			var obj = {};\r\n			obj.type = key;\r\n			var typeKey = type[key];\r\n			for(m,n in typeKey){\r\n				var zong = {};\r\n				var analysis = {};\r\n				var values = new ArrayList();\r\n				list.sort((a,b)=>a.statTime.asDouble()-b.statTime.asDouble());\r\n				var sumValue = 0;\r\n				for(i,j in list){\r\n					var pojo = list[i];\r\n					var tempArray = new ArrayList();\r\n					tempArray.add(pojo[\"statTime\"]);\r\n					tempArray.add(pojo[typeKey[m]].asDouble());\r\n					values.add(tempArray);\r\n				}\r\n				for(i,j in newList){\r\n					var pojo = newList[i];\r\n					var field = map.get(typeKey[m]);\r\n					var value = pojo[field];\r\n					sumValue += value.asDouble();\r\n				}\r\n				analysis.avg =  sumValue.asDouble()/parameter.timeDiff;\r\n				if(key==\"bytes\"){\r\n					analysis.avg = analysis.avg.asDouble() * 8;\r\n				}\r\n				analysis.avg=analysis.avg.toFixed(2)+\"\";\r\n				\r\n				var plist = [];\r\n				for(i,j in values){\r\n					plist.push(values[i][1].asDouble());\r\n				}\r\n				analysis.max = plist.max()+\"\";\r\n				analysis.min = plist.min()+\"\";\r\n				analysis.p95 = getPercentile(plist, 0.95)+\"\";\r\n				\r\n				zong.values = values;\r\n				zong.analysis = analysis;\r\n				\r\n				obj[typeKey[m]] = zong;\r\n			}\r\n			old.add(obj);\r\n		}\r\n		var len = old[0][\"totalBitsRate\"][\"values\"].length;\r\n		for(a,b in old){\r\n			if(old[a].type == \'bytes\' || old[a].type == \'packets\'){\r\n				var other = {};\r\n				var analysis = {};\r\n				var values = new ArrayList();\r\n				var sumValue = 0;\r\n				for(i in range(0,len-1)){\r\n					var sum = 0;\r\n					var tempArray = new ArrayList();\r\n					for(c,d in old[a]){\r\n						if(c != \'type\'){\r\n							if(c.indexOf(\"total\") != -1){\r\n								sum += old[a][c][\"values\"][i][1];\r\n							} else {\r\n								sum