dleNone\' as timeHandle;\r\nimport \'@get:/interface/entity/detail/ip/trafficMap\' as getIpTrafficMap;\r\nimport \'@get:/interface/entity/detail/app/trafficMap\' as getAppTrafficMap;\r\nimport \'@get:/interface/entity/detail/domain/trafficMap\' as getDomainTrafficMap;\r\n/**\r\n * 入参整理 包括调用公共函数\r\n */\r\nvar parameter={\r\n    \"entityType\":entityType,\r\n    \"resource\":resource,\r\n    \"startTime\":startTime,\r\n    \"endTime\":endTime,\r\n    \"country\":countryRegion,\r\n    \"province\":superAdminArea\r\n}\r\ntimeHandle(parameter);\r\nstartTime = parameter.startTime;\r\nendTime = parameter.endTime;\r\n\r\nvar result = {};\r\nif (\"ip\".equals(parameter.entityType)) {\r\n    var ip = parameter.resource;\r\n    result = getIpTrafficMap();\r\n} else if (\"app\".equals(parameter.entityType)) {\r\n    var appName = parameter.resource;\r\n    result = getAppTrafficMap();\r\n} else if (\"domain\".equals(parameter.entityType)) {\r\n    var domain = parameter.resource;\r\n    result = getDomainTrafficMap();\r\n}\r\n\r\nreturn result;');
