INSERT INTO `magic_api_file` VALUES ('/function/postHandle/服务质量通用结果处理.ms', '{\n  \"properties\" : { },\n  \"id\" : \"55b75c2242cc47f4aca5a19071aed2aa\",\n  \"script\" : null,\n  \"groupId\" : \"f174204de29c472e887e5f3ceccc3f01\",\n  \"name\" : \"服务质量通用结果处理\",\n  \"createTime\" : 1672897818951,\n  \"updateTime\" : 1673405135723,\n  \"lock\" : null,\n  \"createBy\" : \"admin\",\n  \"updateBy\" : \"ljy\",\n  \"path\" : \"/qualityOfService\",\n  \"description\" : null,\n  \"returnType\" : null,\n  \"mappingPath\" : null,\n  \"parameters\" : [ {\n    \"name\" : \"result\",\n    \"value\" : null,\n    \"description\" : null,\n    \"required\" : false,\n    \"dataType\" : \"String\",\n    \"type\" : null,\n    \"defaultValue\" : null,\n    \"validateType\" : null,\n    \"error\" : null,\n    \"expression\" : null,\n    \"children\" : null\n  }, {\n    \"name\" : \"field\",\n    \"value\" : null,\n    \"description\" : null,\n    \"required\" : false,\n    \"dataType\" : \"String\",\n    \"type\" : \"java.lang.String\",\n    \"defaultValue\" : null,\n    \"validateType\" : null,\n    \"error\" : null,\n    \"expression\" : null,\n    \"children\" : null\n  }, {\n    \"name\" : \"valueName\",\n    \"value\" : null,\n    \"description\" : null,\n    \"required\" : false,\n    \"dataType\" : \"String\",\n    \"type\" : \"java.lang.String\",\n    \"defaultValue\" : null,\n    \"validateType\" : null,\n    \"error\" : null,\n    \"expression\" : null,\n    \"children\" : null\n  } ]\n}\r\n================================\r\nimport \'@/public/toHump\' as toHump\r\nimport \'@/public/getPercentile\' as getPercentile\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"matrix\";\r\n	o.result = new ArrayList();\r\n	var list = result.data;\r\n\r\n	if(list.length > 0){\r\n		for(i,j in list){\r\n			var pojo = j;\r\n			var tempObj= {};\r\n			for (key,value in pojo){\r\n				var tempKey = toHump(key);\r\n				tempObj[tempKey] = value;\r\n			}\r\n			list[i] = tempObj;\r\n		}\r\n		var fields={};\r\n		for(i in list){\r\n			var value = fields[i[field]];\r\n			var values = new ArrayList();;\r\n			if(value){\r\n				values = fields[i[field]];\r\n				values.add(i);\r\n			}else{\r\n				values = new ArrayList();\r\n				values.add(i);\r\n				fields[i[field]]=values;\r\n			}\r\n		}\r\n\r\n		for(key,value in fields){\r\n			var list = value;\r\n			// 先按照时间排序\r\n			list.sort((a,b)=>a.statTime.asLong() - b.statTime.asLong());\r\n			var values = new ArrayList();\r\n			var aggregation = {};\r\n			aggregation.first = list[0][valueName];\r\n			aggregation.last = list[list.length - 1][valueName];\r\n\r\n			var sumValue = 0\r\n			for(j in list){\r\n				var pojo = j;\r\n				var tempArray = new ArrayList();\r\n				tempArray.add(pojo[\"statTime\"]);\r\n				tempArray.add(pojo[valueName]);\r\n				values.add(tempArray);\r\n				sumValue += pojo[valueName].asDouble();\r\n			}\r\n			aggregation.avg = (sumValue/list.length).toFixed(4);\r\n\r\n			var plist = new ArrayList();\r\n			for(i in values){\r\n				plist.add(i[1]);\r\n			}\r\n			aggregation.p50 = getPercentile(plist, 0.5);\r\n			aggregation.p90 = getPercentile(plist, 0.9);\r\n			aggregation.max = plist.max();\r\n\r\n			var lineObj = {};\r\n			lineObj.values = values;\r\n			lineObj.legend = key;\r\n			lineObj.aggregation = aggregation;\r\n			o.result.add(lineObj);\r\n		}\r\n	}\r\n	o.result = o.result.sort((a,b)=>b.aggregation.avg.asDouble() - a.aggregation.avg.asDouble());\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n}\r\nreturn result');
