INSERT INTO `magic_api_file` VALUES ('/function/preHandle/时间处理无转换.ms', '{\r\n  \"properties\" : { },\r\n  \"id\" : \"9c995d697d8048f8958eaf11d71e0748\",\r\n  \"script\" : null,\r\n  \"groupId\" : \"c054c13da78d46bdb768eaa42d23694b\",\r\n  \"name\" : \"时间处理无转换\",\r\n  \"createTime\" : 1672897818972,\r\n  \"updateTime\" : 1698285405820,\r\n  \"lock\" : null,\r\n  \"createBy\" : \"admin\",\r\n  \"updateBy\" : \"admin\",\r\n  \"path\" : \"/timeHandleNone\",\r\n  \"description\" : null,\r\n  \"returnType\" : null,\r\n  \"mappingPath\" : null,\r\n  \"parameters\" : [ {\r\n    \"name\" : \"parameter\",\r\n    \"value\" : null,\r\n    \"description\" : null,\r\n    \"required\" : false,\r\n    \"dataType\" : \"String\",\r\n    \"type\" : \"java.lang.Object\",\r\n    \"defaultValue\" : null,\r\n    \"validateType\" : null,\r\n    \"error\" : null,\r\n    \"expression\" : null,\r\n    \"children\" : null\r\n  } ]\r\n}\r\n================================\r\nif (parameter.endTime==\"\" || is_null(parameter.endTime)) {\r\n    parameter.endTime = new Date().getTime()/1000;\r\n}\r\nif (parameter.startTime==\"\" || is_null(parameter.startTime)) {\r\n    parameter.startTime = parameter.endTime - 60 * 60;\r\n}\r\n/*计算step,series最多显示100个点，单位：s*/\r\nif((parameter.endTime.asLong() - parameter.startTime.asLong())<=3600){\r\n    parameter.step =  60;\r\n}else if((parameter.endTime.asLong() - parameter.startTime.asLong())<=3*3600){\r\n    parameter.step =  120;\r\n}else if((parameter.endTime.asLong() - parameter.startTime.asLong())<=6*3600){\r\n    parameter.step =  300;\r\n}else if((parameter.endTime.asLong() - parameter.startTime.asLong())<=24*3600){\r\n    parameter.step =  600;\r\n}else if((parameter.endTime.asLong() - parameter.startTime.asLong())<=48*3600){\r\n    parameter.step =  1200;\r\n}else if((parameter.endTime.asLong() - parameter.startTime.asLong())<=168*3600){\r\n    parameter.step =  3600;\r\n}else if((parameter.endTime.asLong() - parameter.startTime.asLong())<=720*3600){\r\n    parameter.step =  3600*6;\r\n}else if((parameter.endTime.asLong() - parameter.startTime.asLong())<=2160*3600){\r\n    parameter.step =  3600*12;\r\n}else if((parameter.endTime.asLong() - parameter.startTime.asLong())<=12*30*24*3600){\r\n    parameter.step =  3600*24;\r\n}\r\nparameter.timeDiff = parameter.endTime.asLong() - parameter.startTime.asLong()\r\nreturn parameter');
INSERT INTO `magic_api_file` VALUES ('/function/preHandle/时间处理有转换.ms', '{\r\n  \"properties\" : { },\r\n  \"id\" : \"copy1671778479626d96635\",\r\n  \"script\" : null,\r\n  \"groupId\" : \"c054c13da78d46bdb768eaa42d23694b\",\r\n  \"name\" : \"时间处理有转换\",\r\n  \"createTime\" : 1672897818975,\r\n  \"updateTime\" : 1698285388501,\r\n  \"lock\" : null,\r\n  \"createBy\" : \"admin\",\r\n  \"updateBy\" : \"admin\",\r\n  \"path\" : \"/timeHandle\",\r\n  \"description\" : null,\r\n  \"returnType\" : null,\r\n  \"mappingPath\" : null,\r\n  \"parameters\" : [ {\r\n    \"name\" : \"parameter\",\r\n    \"value\" : null,\r\n    \"description\" : null,\r\n    \"required\" : false,\r\n    \"dataType\" : \"String\",\r\n    \"type\" : null,\r\n    \"defaultValue\" : null,\r\n    \"validateType\" : null,\r\n    \"error\" : null,\r\n    \"expression\" : null,\r\n    \"children\" : null\r\n  } ]\r\n}\r\n================================\r\nif (parameter.endTime==\"\" || is_null(parameter.endTime)) {\r\n    parameter.endTime = new Date().getTime()/1000;\r\n}\r\nif (parameter.startTime==\"\" || is_null(parameter.startTime)) {\r\n    parameter.startTime = parameter.endTime - 60 * 60;\r\n}\r\n\r\n/*计算step,series最多显示100个点，单位：s*/\r\nif((parameter.endTime.asLong() - parameter.startTime.asLong())<=3600){\r\n    parameter.step =  60;\r\n}else if((parameter.endTime.asLong() - parameter.startTime.asLong())<=3*3600){\r\n    parameter.step =  120;\r\n}else if((parameter.endTime.asLong() - parameter.startTime.asLong())<=6*3600){\r\n    parameter.step =  300;\r\n}else if((parameter.endTime.asLong() - parameter.startTime.asLong())<=24*3600){\r\n    parameter.step =  600;\r\n}else if((parameter.endTime.asLong() - parameter.startTime.asLong())<=48*3600){\r\n    parameter.step =  1200;\r\n}else if((parameter.endTime.asLong() - parameter.startTime.asLong())<=168*3600){\r\n    parameter.step =  3600;\r\n}else if((parameter.endTime.asLong() - parameter.startTime.asLong())<=720*3600){\r\n    parameter.step =  3600*6;\r\n}else if((parameter.endTime.asLong() - parameter.startTime.asLong())<=2160*3600){\r\n    parameter.step =  3600*12;\r\n}else if((parameter.endTime.asLong() - parameter.startTime.asLong())<=12*30*24*3600){\r\n    parameter.step =  3600*24;\r\n}\r\nparameter.timeDiff = parameter.endTime.asLong() - parameter.startTime.asLong()\r\n/*时间转换为toDateTime*/\r\nparameter.endTime = \'toDateTime(\'+parameter.endTime+\')\';\r\nparameter.startTime = \'toDateTime(\'+parameter.startTime+\')\';\r\nreturn parameter\r\n\r\n');
